export function atyabLog() {
  try {
    if (typeof console !== "undefined" && console.log) console.log.apply(console, ["[ATYAB]"].concat([].slice.call(arguments)));
  } catch (e) {}
}

export function apiError(message, status, code) {
  const err = new Error(message);
  err.name = "ApiError";
  err.status = status || 0;
  if (code) err.code = code;
  return err;
}

function mockRoute(url) {
  const u = String(url || "");
  if (u.indexOf("/api/store/is-open") !== -1) return Promise.resolve({ isOpen: true });
  if (u.indexOf("/api/store/settings") !== -1) return mockGetStoreSettings();
  if (u.indexOf("/api/payment-methods") !== -1) return mockGetPaymentMethods();
  if (u.indexOf("/api/offers/all") !== -1) return mockGetOffers();
  if (u.indexOf("/api/reviews") !== -1) return Promise.resolve([]);
  let pm = u.match(/\/api\/products\/(\d+)\/reviews/);
  if (pm) return Promise.resolve([]);
  if (u.indexOf("/api/shipping-carriers") !== -1) return mockGetShippingCarriers();
  if (u.indexOf("/api/products/perfumes") !== -1) return mockGetAllPerfumes();
  if (u.indexOf("/api/products/ouds") !== -1) return mockGetAllOuds();
  if (u.indexOf("/api/products/incenses") !== -1) return mockGetAllIncenses();
  /* ★ R23: محاكي الأصناف الجديدة — فارغ حتى يبني الباك الـViews الخاصة بها */
  if (u.indexOf("/api/products/mists") !== -1) return mockGetAllMists();
  if (u.indexOf("/api/products/lotions") !== -1) return mockGetAllLotions();
  if (u.indexOf("/api/products/mukhamaria") !== -1) return mockGetAllMukhamaria();
  if (u.indexOf("/api/products/hair") !== -1) return mockGetAllHair();
  let m = u.match(/\/api\/Images\/main\/(\d+)/);
  if (m) return mockGetMainImage(Number(m[1]));
  m = u.match(/\/api\/Images\/product\/(\d+)/);
  if (m) return mockGetProductImages(Number(m[1]));
  return null;
}

/* GET يُرجع { data } — مع مهلة، ورسالة خطأ مفهومة لكل فشل */
async function apiGet(url, options) {
  if (isMockApi()) {
    const routed = mockRoute(url);
    if (routed) return routed.then(function (d) { return { data: d }; });
  }
  const timeout = (options && options.timeoutMs) || DEFAULT_TIMEOUT_MS;
  let controller = null;
  let timer = 0;
  const init = { headers: { Accept: "application/json", "ngrok-skip-browser-warning": "true" } };
  if (typeof AbortController === "function") {
    controller = new AbortController();
    init.signal = controller.signal;
    timer = setTimeout(function () {
      controller.abort();
    }, timeout);
  }
  let res;
  try {
    res = await fetch(url, init);
  } catch (e) {
    if (timer) clearTimeout(timer);
    const timeoutHit = e && e.name === "AbortError";
    throw apiError(
      timeoutHit ? "انتهت مهلة الاتصال بالخادم" : "تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API",
      0,
      timeoutHit ? "ECONNABORTED" : "ENETUNREACH"
    );
  }
  if (timer) clearTimeout(timer);
  if (!res.ok) {
    let serverMsg = "";
    try {
      const t = await res.text();
      const j = t ? JSON.parse(t) : null;
      /* ★ مغلّف الخطأ الموحّد: detail العربية أولاً (ProblemDetails) —
         title العام (conflict/not_found/...) يُخفي المعنى الحقيقي */
      serverMsg = (j && (j.detail || j.message || j.title)) || "";
    } catch (e) {
      /* تجاهل */
    }
    const err = apiError(serverMsg || "استجابة الخادم: " + res.status, res.status);
    err.response = { status: res.status, data: { message: serverMsg } };
    throw err;
  }
  const text = await res.text();
  if (!text) return { data: null, status: res.status };
  try {
    return { data: JSON.parse(text), status: res.status };
  } catch (e) {
    throw apiError("استجابة غير صالحة من الخادم", res.status);
  }
}

/* POST يُرجع { data } — نفس المهلة ونفس شكل الخطأ */
async function apiPost(url, body, options) {
  const timeout = (options && options.timeoutMs) || DEFAULT_TIMEOUT_MS;
  let controller = null;
  let timer = 0;
  const init = {
    method: "POST",
    headers: { Accept: "application/json", "Content-Type": "application/json", "ngrok-skip-browser-warning": "true" },
    body: JSON.stringify(body == null ? {} : body)
  };
  if (typeof AbortController === "function") {
    controller = new AbortController();
    init.signal = controller.signal;
    timer = setTimeout(function () {
      controller.abort();
    }, timeout);
  }
  let res;
  try {
    res = await fetch(url, init);
  } catch (e) {
    if (timer) clearTimeout(timer);
    const timeoutHit = e && e.name === "AbortError";
    throw apiError(
      timeoutHit ? "انتهت مهلة الاتصال بالخادم" : "تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API",
      0,
      timeoutHit ? "ECONNABORTED" : "ENETUNREACH"
    );
  }
  if (timer) clearTimeout(timer);
  if (!res.ok) {
    let serverMsg = "";
    try {
      const t = await res.text();
      const j = t ? JSON.parse(t) : null;
      /* ★ detail أولاً — انظر التعليق في apiGet */
      serverMsg = (j && (j.detail || j.message || j.title)) || "";
    } catch (e) {
      /* تجاهل */
    }
    const err = apiError(serverMsg || "استجابة الخادم: " + res.status, res.status);
    err.response = { status: res.status, data: { message: serverMsg } };
    throw err;
  }
  const text = await res.text();
  if (!text) return { data: null, status: res.status };
  try {
    return { data: JSON.parse(text), status: res.status };
  } catch (e) {
    throw apiError("استجابة غير صالحة من الخادم", res.status);
  }
}

export const api = { get: apiGet, post: apiPost };

export function apiUrl(path) {
  const clean = String(path == null ? "" : path);
  if (/^https?:\/\//i.test(clean)) return clean;
  return API_BASE_URL + (clean.charAt(0) === "/" ? clean : "/" + clean);
}

/* يستوعب الأشكال الشائعة: [...] أو {data:[...]} أو {items:[...]} */
export function asList(payload) {
  if (Array.isArray(payload)) return payload;
  if (payload && Array.isArray(payload.data)) return payload.data;
  if (payload && Array.isArray(payload.items)) return payload.items;
  if (payload && Array.isArray(payload.value)) return payload.value;
  return [];
}

/* يستخرج رابطاً واحداً من أشكال الاستجابة المختلفة */
export function asImageUrl(payload) {
  if (!payload) return null;
  if (typeof payload === "string") return payload;
  if (payload.imageUrl) return payload.imageUrl;
  if (payload.url) return payload.url;
  if (payload.src) return payload.src;
  if (Array.isArray(payload) && payload.length) return asImageUrl(payload[0]);
  if (payload.data) return asImageUrl(payload.data);
  return null;
}

/* يستخرج مصفوفة روابط من استجابة صور المنتج */
export function asImageUrlList(payload) {
  const list = asList(payload);
  if (!list.length && typeof payload === "object" && !Array.isArray(payload)) {
    const single = asImageUrl(payload);
    return single ? [single] : [];
  }
  return list.map(asImageUrl).filter(Boolean);
}

/* ------------------------------------------------------------
   روابط Google Drive: رابط المشاركة لا يعمل في <img> مباشرة،
   فنستخرج الـ id ونبني رابط العرض المباشر (thumbnail).
   ------------------------------------------------------------ */
export function driveDirectUrl(link) {
  const raw = String(link == null ? "" : link).trim();
  if (!raw) return null;
  if (/^https:\/\/drive\.google\.com\/thumbnail\?/i.test(raw)) return raw;
  if (/^https:\/\/drive\.google\.com\/uc\?/i.test(raw)) return raw;
  let id = null;
  const m1 = raw.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
  const m2 = raw.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (m1) id = m1[1];
  else if (m2) id = m2[1];
  if (id) return "https://drive.google.com/thumbnail?id=" + id + "&sz=w1000";
  return raw;
}

/* ------------------------------------------------------------
   وضع المحاكاة — بيانات تجريبية بشكل الـ API الحقيقي.
   ------------------------------------------------------------ */
export function isMockApi() {
  try {
    if (typeof window !== "undefined") {
      if (/[?&]mockApi=1/.test(window.location.search)) return true;
      if (window.localStorage.getItem("atyab:mockApi") === "1") return true;
    }
  } catch (e) {
    /* تجاهل */
  }
  return false;
}

