/* ============================================================
   أطياب الجاسم (React) — شريحة المفضلة (wishlistSlice)
   تُخزَّن كأرقام منتجات، ويُحفظ الترتيب كما اختاره العميل (الأحدث في الأعلى).

   ★ v17-W1: عزل المالك والجيل (P0 — كانت العناصر تعبر بين الحسابات).
     · الحالة تحمل ownerId (null = ضيف) + gen؛ والتخزين scoped لكل مالك
       (atyab-wishlist-by-owner) مع مالك مسجل (atyab-wishlist-owner).
     · مخبأ الضيف منفصل؛ دمج الضيف مرة واحدة فقط لكل حساب
       (atyab-wishlist-merged) — بلا دمج حساب سابق، وبلا union-upload
       متكرر يعيد عناصر حُذفت من جهاز آخر.
     · كل مهمة مؤجلة تُلتقط هويتها (cid+gen) قبل الانتظار وتُفحص بعده
       وقبل أي كتابة — رد A المتأخر لا يمس B إطلاقاً.
     · pullWishlist = جلب/مصالحة للحساب الحالي: الخادم مرجع الحقيقة،
       وما يبقى محلياً خارجه يُحفَظ فقط إن كان POST معلقاً فاشلاً
       (dirtyAdd) يُعاد دفعه أولاً. فشل POST/DELETE يظهر للمستخدم
       (wishError) ولا يُبتلع.
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";
import { KEYS, readJSON, writeJSON } from "../persist.js";
import { authFetch } from "../../api/auth.js";
import { ENDPOINTS } from "../api.js";

function cleanIds(arr) {
  if (!Array.isArray(arr)) return [];
  const out = [];
  arr.forEach(function (n) {
    const id = Number(n);
    if (id && out.indexOf(id) === -1) out.push(id);
  });
  return out;
}

function ownerKeyOf(owner) {
  return owner == null ? "guest" : "c:" + String(Number(owner));
}

/* مالك الجلسة لحظة الإقلاع — قراءة متزامنة من نفس مفاتيح userSlice
   (بلا استيراد الشريحة لتفادي الدوران). */
function bootSessionOwner() {
  try {
    const customer = readJSON(KEYS.authCustomer, null);
    const id = customer && customer.id != null ? Number(customer.id) : 0;
    return id > 0 ? id : null;
  } catch (e) {
    return null;
  }
}

function readWishStash() {
  const o = readJSON(KEYS.wishlistByOwner, null);
  return o && typeof o === "object" ? o : {};
}

function readMerged() {
  const o = readJSON(KEYS.wishlistMerged, null);
  return o && typeof o === "object" ? o : {};
}

/* الحالة الأولية: لا نثق بالمفتاح العام القديم (atyab-wishlist) وحده —
   قد يحمل عناصر حساب آخر. المالك المخزّن يقرر التفسير.
   ★ FE19-5: سجل النيات ops (ترتيب + مالك + جيل) وdirtyDel يُحمَّلان مع المخبأ. */
function bootWishlist() {
  const sessionOwner = bootSessionOwner();
  const stash = readWishStash();
  const merged = readMerged();
  let storedOwner = null;
  try {
    const raw = readJSON(KEYS.wishlistOwner, null);
    if (raw != null && Number(raw) > 0) storedOwner = Number(raw);
  } catch (e) {
    storedOwner = null;
  }
  const legacy = cleanIds(readJSON(KEYS.wishlist, []));
  /* هجرة لمرة واحدة: عناصر المفتاح القديم تخص مالكه المخزّن (أو الضيف) */
  if (legacy.length && storedOwner != null) {
    const k = ownerKeyOf(storedOwner);
    if (!stash[k] || !stash[k].ids || !stash[k].ids.length) {
      stash[k] = { ids: legacy, dirtyAdd: [] };
      try { writeJSON(KEYS.wishlistByOwner, stash); } catch (e) {}
    }
  }
  const curKey = ownerKeyOf(sessionOwner);
  const cur = (sessionOwner != null && storedOwner !== sessionOwner)
    ? (stash[curKey] || null) /* جلسة مختلفة عن المخزّن: مخبأها فقط — لا عناصر الغير */
    : (stash[curKey] || (sessionOwner == null && legacy.length ? { ids: legacy, dirtyAdd: [] } : null));
  const ids = cur && Array.isArray(cur.ids) ? cleanIds(cur.ids) : [];
  const bootOps = cur && Array.isArray(cur.ops) ? cleanWishOps(cur.ops) : [];
  try {
    let mx = 0;
    bootOps.forEach(function (o) { if (Number(o.seq) > mx) mx = Number(o.seq); });
    primeWishSeq(mx);
  } catch (e) {}
  return {
    ids: ids,
    ownerId: sessionOwner,
    gen: 0,
    wishError: null,
    syncError: false,
    dirtyAdd: cur && Array.isArray(cur.dirtyAdd) ? cleanIds(cur.dirtyAdd) : [],
    dirtyDel: cur && Array.isArray(cur.dirtyDel) ? cleanIds(cur.dirtyDel) : [],
    ops: bootOps,
    merged: merged
  };
}

/* ★ FE19-5: تطهير سجل النيات المحمّل — عناصر صالحة فقط. */
export function cleanWishOps(arr) {
  if (!Array.isArray(arr)) return [];
  const out = [];
  arr.forEach(function (o) {
    if (!o || typeof o !== "object") return;
    const id = Number(o.id);
    const seq = Number(o.seq);
    if (!id || !seq) return;
    const type = o.type === "remove" ? "remove" : "add";
    const state = o.state === "failed" ? "failed" : "pending";
    out.push({ seq: seq, type: type, id: id, cid: o.cid != null ? Number(o.cid) : null, gen: o.gen != null ? Number(o.gen) : null, state: state, at: Number(o.at) || 0 });
  });
  out.sort(function (a, b) { return a.seq - b.seq; });
  return out.slice(Math.max(0, out.length - 500));
}

let wishOpSeq = 0;
export function nextWishSeq() {
  wishOpSeq += 1;
  return wishOpSeq;
}
/* أعلى seq محمّل — حتى لا يتكرر الترتيب بعد الإقلاع (الهوية ≠ الترتيب). */
export function primeWishSeq(n) {
  const v = Number(n) || 0;
  if (v > wishOpSeq) wishOpSeq = Math.floor(v);
}

/* ★ FE19-5: مصالحة خالصة — الخادم مرجع الحقيقة + النوايا المعلقة بترتيبها.
   final = server ∪ dirtyAdd، ثم تُطبَّق ops المعلقة (pending دائماً، وfailed
   ما لم تُستثنَ) بالترتيب: add تُظهر وremove تُخفي — نية المستخدم الأحدث
   تفوز (remove→add حاضر، add→remove غائب)، وGET قديم لا يلغي نية أحدث
   لأن السجل يُقرأ بعد الرد.
   excludeSeqs: نيات remove فشلت في هذا السحب نفسه — تُستثنى من الإخفاء
   فيُعرض حقيقة الخادم (rollback ظاهر + خطأ) مع بقاء النية failed للسحب
   التالي؛ أما adds الفاشلة فتبقى ظاهرة (ثبات الإضافة الفاشلة F02). */
export function reconcileWishIds(serverIds, dirtyAdd, ops, excludeSeqs) {
  const excl = {};
  (excludeSeqs || []).forEach(function (s) { excl[Number(s)] = true; });
  const set = {};
  (serverIds || []).forEach(function (n) { const id = Number(n); if (id) set[id] = true; });
  (dirtyAdd || []).forEach(function (n) { const id = Number(n); if (id) set[id] = true; });
  const sorted = (ops || []).filter(function (o) {
    if (!o || !Number(o.id) || !Number(o.seq)) return false;
    if (o.state !== "pending" && o.state !== "failed") return false;
    if (o.state === "failed" && o.type === "remove" && excl[Number(o.seq)]) return false;
    return true;
  }).sort(function (a, b) { return Number(a.seq) - Number(b.seq); });
  const lastType = {};
  sorted.forEach(function (op) {
    const id = Number(op.id);
    lastType[id] = op.type === "remove" ? "remove" : "add";
    if (op.type === "remove") delete set[id];
    else set[id] = true;
  });
  return { ids: Object.keys(set).map(function (k) { return Number(k); }), lastType: lastType };
}

/* ★ FE19-5: نيات مستغرَقة — عند نجاح mutation لنية seq على عنصر بنوع kind،
   كل نيات النوع نفسه الأقدم (seq <= upToSeq) تحقق غايتها (الحالة المؤكدة
   نفسها) فتُقر معها؛ نيات النوع الآخر أو الأحدث لا تُمس (إقرار نسبي للـop
   الصحيح، لا كل عمليات المنتج). خالصة على مصفوفة ops (للاختبار). */
export function subsumedWishSeqs(ops, id, kind, upToSeq) {
  const out = [];
  (ops || []).forEach(function (o) {
    if (!o || Number(o.id) !== Number(id)) return;
    if (kind === "remove" ? o.type !== "remove" : o.type !== "add") return;
    if (o.state !== "pending" && o.state !== "failed") return;
    if (Number(o.seq) > Number(upToSeq)) return;
    out.push(Number(o.seq));
  });
  return out;
}

/* ★ FE19-5: أحدث نية معلقة على العنصر بعد seq معين — سياسة الـrollback
   تحترمها: فشل remove مع نية remove أحدث = لا استعادة عمياء؛ مع نية add
   أحدث أو بلا نية أحدث = استعادة تعكس حقيقة الخادم + خطأ ظاهر. */
export function newestWishOp(ops, id, afterSeq) {
  let best = null;
  (ops || []).forEach(function (o) {
    if (!o || Number(o.id) !== Number(id)) return;
    if (Number(o.seq) <= Number(afterSeq)) return;
    if (o.state !== "pending" && o.state !== "failed") return;
    if (!best || Number(o.seq) > Number(best.seq)) best = o;
  });
  return best;
}

/* حارس المالك بعد كل انتظار — نفس عقد السلة (F3) */
function wishOwnerValid(getState, cidAtStart, genAtStart) {
  try {
    const s = getState();
    const cidNow = Number(s.user && s.user.auth && s.user.auth.customerId) || 0;
    if (Number(cidAtStart || 0) !== Number(cidNow || 0)) return false;
    if (genAtStart != null) {
      const w = getState().wishlist || {};
      const genNow = Number((s.user && s.user.auth && s.user.auth.gen) || 0);
      if (Number(genAtStart) !== Number(genNow)) return false;
      if (w.ownerId != null && Number(w.ownerId) !== Number(cidNow || 0)) return false;
      if (w.ownerId == null && cidNow) return false;
    }
    return true;
  } catch (e) { return false; }
}

const slice = createSlice({
  name: "wishlist",
  initialState: bootWishlist(),
  reducers: {
    toggle: function (state, action) {
      const id = Number(action.payload);
      if (!id) return;
      const at = state.ids.indexOf(id);
      if (at === -1) {
        state.ids.unshift(id);
      } else {
        state.ids.splice(at, 1);
        state.dirtyAdd = (state.dirtyAdd || []).filter(function (n) { return n !== id; });
      }
    },
    add: function (state, action) {
      const id = Number(action.payload);
      if (id && state.ids.indexOf(id) === -1) state.ids.unshift(id);
    },
    /* ★ FE17-F02: تسجيل نية الإضافة قبل الشبكة — تُستدعى من الـthunk
       لحظة الـdispatch؛ تُسقط عند الإقرار فقط (wishDirtyDrop). */
    addIntended: function (state, action) {
      const id = Number(action.payload);
      if (!id) return;
      const cur = cleanIds(state.dirtyAdd);
      if (cur.indexOf(id) === -1) state.dirtyAdd = cur.concat([id]);
    },
    /* ★ FE17-F02: rollback الحذف يعيد العنصر محلياً — لا dirtyDel.
       إلغاء نية إضافة معلقة لنفس العنصر (أُزيل قبل إقراره). */
    remove: function (state, action) {
      const id = Number(action.payload);
      state.ids = state.ids.filter(function (n) {
        return n !== id;
      });
      state.dirtyAdd = (state.dirtyAdd || []).filter(function (n) { return n !== id; });
    },
    /* ★ FE17-F02: rollback ظاهر للحذف الفاشل — يعيد العنصر إن غاب. */
    rollbackAdd: function (state, action) {
      const id = Number(action.payload);
      if (!id) return;
      if (state.ids.indexOf(id) === -1) state.ids.unshift(id);
    },
    clear: function (state) {
      state.ids = [];
      state.dirtyAdd = [];
      state.dirtyDel = [];
      state.ops = [];
    },
    /* استبدال كامل من مصالحة الخادم — تُستدعى بحراسة المالك قبلها */
    wishesReplaced: function (state, action) {
      const p = action.payload || {};
      const list = Array.isArray(p) ? p : p.ids;
      state.ids = cleanIds(list);
      if (p && p.dirtyAdd) state.dirtyAdd = cleanIds(p.dirtyAdd);
      state.syncError = false;
    },
    /* ★ v17-W1: تبديل الحساب — فصل كامل.
       from مسجل → خبّئ {ids,dirtyAdd,dirtyDel,ops} في مخبئه؛ to → حمّل مخبأه
       (أو [] )؛ الأخطاء تُصفَّر؛ الدمج المنجز يبقى (مرة واحدة فقط).
       ★ FE19-5: سجل النيات يُخبَّأ مع المالك — نيات A لا تُطبَّق على B. */
    wishOwnerSwitched: function (state, action) {
      const p = (action && action.payload) || {};
      const hasPayload = action && action.payload != null;
      const storedOwner = state.ownerId != null ? Number(state.ownerId) : null;
      let from = hasPayload ? (p.from == null ? null : Number(p.from) || null) : storedOwner;
      const to = hasPayload ? (p.to == null ? null : Number(p.to) || null) : storedOwner;
      if (from == null && storedOwner != null) from = storedOwner;
      try {
        const stash = readWishStash();
        stash[ownerKeyOf(from)] = {
          ids: cleanIds(state.ids),
          dirtyAdd: cleanIds(state.dirtyAdd),
          dirtyDel: cleanIds(state.dirtyDel),
          ops: cleanWishOps(state.ops)
        };
        try { writeJSON(KEYS.wishlistByOwner, stash); } catch (e) {}
        const next = stash[ownerKeyOf(to)] || null;
        state.ids = next && Array.isArray(next.ids) ? cleanIds(next.ids) : [];
        state.dirtyAdd = next && Array.isArray(next.dirtyAdd) ? cleanIds(next.dirtyAdd) : [];
        state.dirtyDel = next && Array.isArray(next.dirtyDel) ? cleanIds(next.dirtyDel) : [];
        state.ops = next && Array.isArray(next.ops) ? cleanWishOps(next.ops) : [];
      } catch (e) {
        state.ids = [];
        state.dirtyAdd = [];
        state.dirtyDel = [];
        state.ops = [];
      }
      state.ownerId = to;
      state.gen = p.gen != null ? Number(p.gen) || 0 : state.gen;
      state.wishError = null;
      state.syncError = false;
      try { writeJSON(KEYS.wishlistOwner, to == null ? 0 : Number(to)); } catch (e) {}
    },
    wishMergeDone: function (state, action) {
      const o = Number(action.payload) || 0;
      if (!o) return;
      state.merged = Object.assign({}, state.merged, { [String(o)]: true });
      try { writeJSON(KEYS.wishlistMerged, state.merged); } catch (e) {}
    },
    wishErrorSet: function (state, action) {
      const p = action.payload || {};
      state.wishError = {
        text: String(p.text || "تعذّرت مزامنة المفضلة — تحقق من الاتصال."),
        textEn: String(p.textEn || p.text || "Could not sync the wishlist — check your connection."),
        at: Date.now()
      };
    },
    wishErrorClear: function (state) {
      state.wishError = null;
    },
    /* ★ FE19-5: تسجيل نية مرتبة (مالك + جيل) — تُستدعى من الـthunk لحظة
       الـdispatch مع seq مُسند مسبقاً. نية add لاحقة تسقط dirtyDel لنفس
       العنصر (الأحدث يفوز)، ونية remove لاحقة تسقط dirtyAdd. النية تُسجَّل
       أيضاً في مجموعة dirty الموافقة كمرآة (تُسقط عند الإقرار فقط). */
    wishOpRecorded: function (state, action) {
      const p = action.payload || {};
      const id = Number(p.id);
      const seq = Number(p.seq);
      if (!id || !seq) return;
      const type = p.type === "remove" ? "remove" : "add";
      const exists = (state.ops || []).some(function (o) { return Number(o.seq) === seq; });
      if (!exists) {
        state.ops = (state.ops || []).concat([{ seq: seq, type: type, id: id, cid: p.cid != null ? Number(p.cid) : null, gen: p.gen != null ? Number(p.gen) : null, state: "pending", at: Date.now() }]);
        if (state.ops.length > 500) state.ops = state.ops.slice(state.ops.length - 500);
      }
      if (type === "add") {
        state.dirtyDel = (state.dirtyDel || []).filter(function (n) { return n !== id; });
        const da = cleanIds(state.dirtyAdd);
        if (da.indexOf(id) === -1) state.dirtyAdd = da.concat([id]);
      } else {
        state.dirtyAdd = (state.dirtyAdd || []).filter(function (n) { return n !== id; });
        const dd = cleanIds(state.dirtyDel);
        if (dd.indexOf(id) === -1) state.dirtyDel = dd.concat([id]);
      }
    },
    /* ★ FE19-5: إقرار نيات محددة (seqs المهمة نفسها) — لا كل عمليات المنتج.
       dirty تُسقط للعنصر فقط إن لم تبقَ نية معلقة أخرى من نفس النوع عليه. */
    wishOpsAck: function (state, action) {
      const p = action.payload || {};
      const seqs = {};
      (Array.isArray(p.seqs) ? p.seqs : []).forEach(function (s) { seqs[Number(s)] = true; });
      const id = Number(p.id);
      const kind = p.kind === "remove" ? "remove" : "add";
      state.ops = (state.ops || []).filter(function (o) { return !seqs[Number(o.seq)]; });
      if (id) {
        const still = (state.ops || []).some(function (o) {
          return Number(o.id) === id && (o.state === "pending" || o.state === "failed") &&
            (kind === "remove" ? o.type === "remove" : o.type === "add");
        });
        if (!still) {
          if (kind === "remove") state.dirtyDel = (state.dirtyDel || []).filter(function (n) { return n !== id; });
          else state.dirtyAdd = (state.dirtyAdd || []).filter(function (n) { return n !== id; });
        }
      }
    },
    /* ★ FE19-5: تعليم نية فاشلة (تبقى معلقة لل retry) — تُستدعى عند فشل mutation.
       تُبقي أيضاً علامة dirty الموافقة (إعادة الدفع في السحب التالي). */
    wishOpFailed: function (state, action) {
      const seqs = {};
      (Array.isArray(action.payload) ? action.payload : []).forEach(function (s) { seqs[Number(s)] = true; });
      (state.ops || []).forEach(function (o) {
        if (!seqs[Number(o.seq)]) return;
        o.state = "failed";
        const id = Number(o.id);
        if (!id) return;
        if (o.type === "remove") {
          const dd = cleanIds(state.dirtyDel);
          if (dd.indexOf(id) === -1) state.dirtyDel = dd.concat([id]);
        } else {
          const da = cleanIds(state.dirtyAdd);
          if (da.indexOf(id) === -1) state.dirtyAdd = da.concat([id]);
        }
      });
    },
    wishDirtyDrop: function (state, action) {
      const id = Number(action.payload);
      if (!id) return;
      state.dirtyAdd = (state.dirtyAdd || []).filter(function (n) { return n !== id; });
    },
    wishSyncSet: function (state, action) {
      state.syncError = action.payload !== false;
    }
  }
});

export const wishlistActions = slice.actions;
export const wishlistReducer = slice.reducer;
export const selectWishlistIds = function (state) {
  return state.wishlist.ids;
};
export const selectWishlistCount = function (state) {
  return state.wishlist.ids.length;
};
/* ★ الشارة محلية ومربوطة بالمالك (ownerId) — لا GET على الرسم (U1) */
export const selectWishlistOwner = function (state) {
  return state.wishlist.ownerId != null ? Number(state.wishlist.ownerId) : null;
};

/* ============================================================
   مزامنة المفضلة مع الخادم (للأعضاء فقط — الضيف محلي خالص)
   ★ v17: سحب/مصالحة للحساب الحالي + دمج ضيف مرة واحدة + أخطاء ظاهرة
   ★ FE17-F02: سجل نيات الإضافة قبل الشبكة — dirtyAdd تُسجَّل لحظة
   الـdispatch وتُسقط عند الإقرار فقط؛ الدمج يتحقق من status كل POST
   ويحتفظ بالفاشل؛ المصالحة تُعيد تطبيق غير المُقر بعد GET؛ الحذف
   الفاشل rollback ظاهر.
   ★ FE19-5: سجل نيات مرتب (ops: seq+نوع+مالك+جيل) للإضافة والحذف معاً —
   الدفع نيةً نيةً بالترتيب، والإقرار نسبي للمستغرَق (لا كل عمليات المنتج)،
   والمصالحة reconcileWishIds بعد كل GET (الأحدث يفوز)، وrollback الحذف
   يحترم النية الأحدث، وdirtyDel مرآة لنيات الحذف المعلقة (تُحفظ دائماً).
   ============================================================ */

function serverCustomerId(getState) {
  try {
    const s = getState();
    return Number(s.user && s.user.auth && s.user.auth.customerId) || 0;
  } catch (e) {
    return 0;
  }
}
function currentGen(getState) {
  try {
    return Number(getState().user && getState().user.auth && getState().user.auth.gen) || 0;
  } catch (e) { return 0; }
}

let wishChain = Promise.resolve();
function queueWish(fn) {
  wishChain = wishChain.then(fn, fn);
}

async function readJsonSafe(res) {
  try {
    const t = await res.text();
    return t ? JSON.parse(t) : null;
  } catch (e) {
    return null;
  }
}

function wishIdsOf(payload) {
  let list = null;
  if (Array.isArray(payload)) list = payload;
  else if (payload && Array.isArray(payload.items)) list = payload.items;
  else if (payload && Array.isArray(payload.data)) list = payload.data;
  else if (payload && Array.isArray(payload.wishlist)) list = payload.wishlist;
  if (!list) return [];
  const out = [];
  list.forEach(function (o) {
    const v = o != null && typeof o === "object" ? o.productId != null ? o.productId : o.id : o;
    const id = Number(v);
    if (id && out.indexOf(id) === -1) out.push(id);
  });
  return out;
}

function mergeErrMsg(lang) {
  return lang === "en"
    ? "Wishlist sync failed — your list on this device is kept."
    : "تعذّرت مزامنة المفضلة — قائمتك على هذا الجهاز محفوظة.";
}

/* سحب + مصالحة — تُستدعى عند كل دخول لصفحة المفضلة (W2)
   ★ FE17-F02: دفع النوايا المعلقة أولاً (إسقاط عند الإقرار فقط)، ثم GET،
   ثم دمج/مصالحة مع إعادة تطبيق غير المُقر بعد الرد — لا يمحو GET قديم
   تعديلاً أحدث سُجّل أثناء انتظاره.
   ★ FE19-5: الدفع يعالج سجل ops مرتباً (seq) نيةً نيةً — POST للإضافة
   وDELETE للحذف بالترتيب الأصلي (remove→add وadd→remove يصلان الخادم
   بترتيبهما)، والإقرار نسبي للـseq نفسه (wishOpsAck) لا كل عمليات المنتج.
   DELETE على عنصر غائب (404) وPOST على عنصر موجود (409) يُقران (idempotent)
   بدل إعادة لا نهائية. بعد GET يُعاد قراءة السجل ويُطبَّق reconcileWishIds
   — ردٌّ بدأ قبل نية أحدث لا يلغيها. */
function pendingWishOps(getState) {
  const ops = ((getState().wishlist || {}).ops) || [];
  return ops.filter(function (o) {
    return o && (o.state === "pending" || o.state === "failed") && Number(o.id) && Number(o.seq);
  }).sort(function (a, b) { return Number(a.seq) - Number(b.seq); });
}

/* دفع نية واحدة — يعيد true عند محاولة شبكة فعلية.
   ★ FE19-5: فشل remove هنا = rollback ظاهر (حقيقة الخادم) + تسجيل الـseq
   في failedRemoveSeqs لتُستثنى من مصالحة هذا السحب (العرض: موجود + خطأ)،
   والنية تبقى failed للسحب التالي. */
async function pushOneWishOp(dispatch, getState, cid, genAtStart, op, failedRemoveSeqs) {
  if (!wishOwnerValid(getState, cid, genAtStart)) return false;
  const id = Number(op.id);
  const seq = Number(op.seq);
  const isRemove = op.type === "remove";
  try {
    const res = isRemove
      ? await authFetch(ENDPOINTS.wishRemove(cid, id), { method: "DELETE" })
      : await authFetch(ENDPOINTS.wishOf(cid), { method: "POST", body: { productId: id } });
    if (!wishOwnerValid(getState, cid, genAtStart)) return true;
    if (res.status === 403 || res.status === 401) return true;
    /* idempotent: حذف غائب (404) أو إضافة موجودة (409) = الغاية متحققة */
    const ackAs = (res.ok || (isRemove && res.status === 404) || (!isRemove && res.status === 409));
    if (ackAs) {
      const seqs = subsumedWishSeqs((getState().wishlist || {}).ops, id, isRemove ? "remove" : "add", seq);
      if (seqs.indexOf(seq) === -1) seqs.push(seq);
      dispatch(wishlistActions.wishOpsAck({ seqs: seqs, id: id, kind: isRemove ? "remove" : "add" }));
      return true;
    }
    dispatch(wishlistActions.wishOpFailed([seq]));
    if (isRemove) {
      dispatch(wishlistActions.rollbackAdd(id));
      if (failedRemoveSeqs) failedRemoveSeqs.push(seq);
    }
    return true;
  } catch (e) {
    if (!wishOwnerValid(getState, cid, genAtStart)) return true;
    dispatch(wishlistActions.wishOpFailed([seq]));
    if (isRemove) {
      dispatch(wishlistActions.rollbackAdd(id));
      if (failedRemoveSeqs) failedRemoveSeqs.push(seq);
    }
    return true;
  }
}

export function pullWishlist() {
  return function (dispatch, getState) {
    const cid = serverCustomerId(getState);
    if (!cid) return Promise.resolve();
    const genAtStart = currentGen(getState);
    return new Promise(function (done) {
      queueWish(async function () {
        if (!wishOwnerValid(getState, cid, genAtStart)) return done();
        let pushFailed = false;
        let pushedAny = false;
        try {
          const st0 = getState().wishlist || {};
          const alreadyMerged = !!(st0.merged && st0.merged[String(cid)]);
          /* ★ دمج الضيف مرة واحدة فقط: عناصر مخبأ الضيف (لا الحساب السابق) */
          let guestIds = [];
          if (!alreadyMerged) {
            try {
              const stash = readWishStash();
              const g = stash[ownerKeyOf(null)] || null;
              guestIds = g && Array.isArray(g.ids) ? cleanIds(g.ids) : [];
            } catch (e) { guestIds = []; }
          }
          /* ★ FE19-5: ادفع سجل النيات مرتباً (seq) نيةً نيةً — الإسقاط عند
             الإقرار النسبي فقط؛ الفاشل يبقى failed للسحب التالي. */
          const pending = pendingWishOps(getState);
          const failedRemoveSeqs = [];
          for (let i = 0; i < pending.length; i++) {
            if (!wishOwnerValid(getState, cid, genAtStart)) return done();
            const before = ((getState().wishlist || {}).ops || []).filter(function (o) {
              return Number(o.seq) === Number(pending[i].seq) && (o.state === "pending" || o.state === "failed");
            }).length;
            if (!before) continue; /* أُقرّت أثناء الانتظار بمرآة أحدث */
            const attempted = await pushOneWishOp(dispatch, getState, cid, genAtStart, pending[i], failedRemoveSeqs);
            if (attempted) pushedAny = true;
            if (!wishOwnerValid(getState, cid, genAtStart)) return done();
            const still = ((getState().wishlist || {}).ops || []).some(function (o) {
              return Number(o.seq) === Number(pending[i].seq) && o.state === "failed";
            });
            if (still) pushFailed = true;
          }
          const res = await authFetch(ENDPOINTS.wishOf(cid), { method: "GET" });
          if (!wishOwnerValid(getState, cid, genAtStart)) return done();
          if (res.status === 403 || res.status === 401) return done();
          if (res.status !== 404 && !res.ok) {
            dispatch(wishlistActions.wishSyncSet(true));
            refreshWishError(dispatch, getState, true, pushedAny);
            return done();
          }
          const serverIds = res.status === 404 ? [] : wishIdsOf(await readJsonSafe(res));
          if (!wishOwnerValid(getState, cid, genAtStart)) return done();
          /* ★ FE19-5: إعادة قراءة السجل بعد الرد — نية سُجّلت أثناء GET/الدفع
             تُطبَّق ولا يلغيها الرد القديم. */
          const opsNow = ((getState().wishlist || {}).ops) || [];
          const dirtyNow = cleanIds((getState().wishlist || {}).dirtyAdd);
          if (!alreadyMerged && guestIds.length) {
            /* ★ FE17-F02: الدمج يُستهلك مرة واحدة — سجّل النيات مقدماً،
               وتحقق من status كل POST؛ الفاشل يبقى نية معلقة تُعاد كل سحب.
               ★ FE19-5: نيات الدمج في سجل ops (ترتيب + إقرار نسبي). */
            const missing = guestIds.filter(function (id) {
              return serverIds.indexOf(id) === -1;
            });
            const union = serverIds.slice();
            guestIds.forEach(function (id) {
              if (union.indexOf(id) === -1) union.push(id);
            });
            let mergeFailed = false;
            for (let i = 0; i < missing.length; i++) {
              if (!wishOwnerValid(getState, cid, genAtStart)) return done();
              const mseq = nextWishSeq();
              dispatch(wishlistActions.addIntended(missing[i]));
              dispatch(wishlistActions.wishOpRecorded({ seq: mseq, type: "add", id: missing[i], cid: cid, gen: genAtStart }));
              try {
                const pr = await authFetch(ENDPOINTS.wishOf(cid), { method: "POST", body: { productId: missing[i] } });
                if (!wishOwnerValid(getState, cid, genAtStart)) return done();
                if (pr.status === 403 || pr.status === 401) return done();
                pushedAny = true;
                if (pr.ok || pr.status === 409) {
                  const seqs = subsumedWishSeqs((getState().wishlist || {}).ops, missing[i], "add", mseq);
                  if (seqs.indexOf(mseq) === -1) seqs.push(mseq);
                  dispatch(wishlistActions.wishOpsAck({ seqs: seqs, id: missing[i], kind: "add" }));
                  dispatch(wishlistActions.wishDirtyDrop(missing[i]));
                  dropIdFromGuestStash(missing[i]);
                } else {
                  dispatch(wishlistActions.wishOpFailed([mseq]));
                  mergeFailed = true;
                }
              } catch (e) {
                if (!wishOwnerValid(getState, cid, genAtStart)) return done();
                pushedAny = true;
                dispatch(wishlistActions.wishOpFailed([mseq]));
                mergeFailed = true;
              }
            }
            if (!wishOwnerValid(getState, cid, genAtStart)) return done();
            /* عرض الدمج مع احترام أي نية أحدث سُجّلت أثناء POSTs */
            const opsAfter = ((getState().wishlist || {}).ops) || [];
            const dirtyAfter = cleanIds((getState().wishlist || {}).dirtyAdd);
            dispatch(wishlistActions.wishesReplaced({ ids: reconcileWishIds(union, dirtyAfter, opsAfter, failedRemoveSeqs).ids }));
            dispatch(wishlistActions.wishMergeDone(cid));
            refreshWishError(dispatch, getState, pushFailed || mergeFailed, pushedAny ? true : ((pending.length > 0 || missing.length > 0) ? true : false));
          } else {
            /* ★ FE19-5: المصالحة = الخادم مرجع الحقيقة + dirtyAdd + سجل ops
               (الأحدث يفوز) — لا رفع لعناصر حُذفت من جهاز آخر، ولا محو
               لنية أحدث من الـGET، ولا مسح لعلامة حذف سُجّلت قبل الـGET.
               نية remove فشلت في هذا السحب تُستثنى (حقيقة الخادم + خطأ). */
            if (!wishOwnerValid(getState, cid, genAtStart)) return done();
            dispatch(wishlistActions.wishesReplaced({ ids: reconcileWishIds(serverIds, dirtyNow, opsNow, failedRemoveSeqs).ids }));
            if (!alreadyMerged) dispatch(wishlistActions.wishMergeDone(cid));
            refreshWishError(dispatch, getState, pushFailed, pushedAny ? true : (pending.length > 0 ? true : false));
          }
          dispatch(wishlistActions.wishSyncSet(false));
        } catch (e) {
          try { dispatch(wishlistActions.wishSyncSet(true)); } catch (e2) {}
        } finally {
          done();
        }
      });
    });
  };
}

/* ★ FE17-F02: إسقاط عنصر من مخبأ الضيف بعد إقرار دمجه (يُستهلك مرة واحدة) */
function dropIdFromGuestStash(id) {
  try {
    const stash = readWishStash();
    const g = stash[ownerKeyOf(null)] || null;
    if (!g || !Array.isArray(g.ids)) return;
    const rest = cleanIds(g.ids).filter(function (n) { return n !== Number(id); });
    if (rest.length === cleanIds(g.ids).length) return;
    stash[ownerKeyOf(null)] = Object.assign({}, g, { ids: rest });
    writeJSON(KEYS.wishlistByOwner, stash);
  } catch (e) {}
}

/* ★ FE17-F02: خطأ ظاهر عند فشل دفع، ومسح عند اكتمال الإقرار فقط.
   نيات جديدة سُجّلت أثناء العمل لا تُظهر خطأً بذاتها — مرآتها تقرر.
   ★ FE18: السحب (pull) لا يمسح خطأً سابقاً ما لم تُدفع فيه نية فعلاً —
   فشل DELETE سابق (rollback ظاهر + خطأ) لا تمحوه مصالحة لاحقة لم تدفع
   شيئاً، وإلا ضاعت نية الحذف بصمت (المحلي والخادم متوافقان شكلاً لكن
   المستخدم أراد الحذف). المسح فقط عند: فشل جديد (يُثبَّت الخطأ) أو دفع
   ناجح لنية معلقة في هذا السحب/المرآة مع فراغ المعلق.
   ★ FE19-5: المعلق = dirtyAdd ∪ dirtyDel ∪ نيات ops (pending/failed). */
function refreshWishError(dispatch, getState, failed, pushedAny) {
  try {
    const lang = (getState().ui && getState().ui.language) || "ar";
    if (failed) {
      dispatch(wishlistActions.wishErrorSet({ text: mergeErrMsg(lang) }));
      return;
    }
    if (pushedAny === false) return; /* سحب بلا دفع: أبقِ الخطأ السابق */
    const w = getState().wishlist || {};
    const pending = cleanIds(w.dirtyAdd).concat(cleanIds(w.dirtyDel));
    const hasOps = ((w.ops) || []).some(function (o) { return o && (o.state === "pending" || o.state === "failed"); });
    if (!pending.length && !hasOps) dispatch(wishlistActions.wishErrorClear());
  } catch (e) {}
}

/* ★ FE19-5: سياسة rollback للحذف الفاشل تحترم الأحدث — تُستدعى بعد
   wishOpFailed([seq]). نية remove أحدث على العنصر = لا استعادة (نيتها
   تحكم)؛ نية add أحدث أو لا نية = استعادة تعكس حقيقة الخادم + خطأ ظاهر. */
function rollbackRemoveRespectingNewer(dispatch, getState, num, seq) {
  const newer = newestWishOp(((getState().wishlist || {}).ops) || [], num, seq);
  if (!newer || newer.type === "add") {
    dispatch(wishlistActions.rollbackAdd(num));
  }
}
function wishLang(getState) {
  try { return (getState().ui && getState().ui.language) || "ar"; } catch (e) { return "ar"; }
}

/* إضافة صريحة مع مرآة فورية للخادم (تُظهر الفشل).
   ★ FE17-F02: النية تُسجَّل قبل الشبكة (تبقى عند الاستثناء/الفشل
   وتُعاد كل سحب) وتُسقط عند الإقرار فقط.
   ★ FE19-5: النية في سجل ops (seq+مالك+جيل)؛ النجاح يُقر النيات المستغرَقة
   (نفس النوع الأقدم) لا كل عمليات المنتج؛ POST على موجود (409) يُقر. */
export function addWish(id) {
  return function (dispatch, getState) {
    const num = Number(id);
    if (!num) return;
    dispatch(wishlistActions.add(num));
    const cid = serverCustomerId(getState);
    if (!cid) return;
    const genAtStart = currentGen(getState);
    const seq = nextWishSeq();
    dispatch(wishlistActions.addIntended(num));
    dispatch(wishlistActions.wishOpRecorded({ seq: seq, type: "add", id: num, cid: cid, gen: genAtStart }));
    queueWish(async function () {
      if (!wishOwnerValid(getState, cid, genAtStart)) return;
      try {
        const res = await authFetch(ENDPOINTS.wishOf(cid), { method: "POST", body: { productId: num } });
        if (!wishOwnerValid(getState, cid, genAtStart)) return;
        if (res.status === 403 || res.status === 401) return;
        if (res.ok || res.status === 409) {
          const seqs = subsumedWishSeqs((getState().wishlist || {}).ops, num, "add", seq);
          if (seqs.indexOf(seq) === -1) seqs.push(seq);
          dispatch(wishlistActions.wishOpsAck({ seqs: seqs, id: num, kind: "add" }));
          dispatch(wishlistActions.wishDirtyDrop(num));
          refreshWishError(dispatch, getState, false, true);
        } else {
          dispatch(wishlistActions.wishOpFailed([seq]));
          dispatch(wishlistActions.wishErrorSet({ text: mergeErrMsg(wishLang(getState)) }));
        }
      } catch (e) {
        if (!wishOwnerValid(getState, cid, genAtStart)) return;
        dispatch(wishlistActions.wishOpFailed([seq]));
        dispatch(wishlistActions.wishErrorSet({ text: mergeErrMsg(wishLang(getState)) }));
      }
    });
  };
}

/* تبديل مع مرآة فورية للخادم (تُظهر الفشل).
   ★ FE17-F02: التشغيل نية مسبقة؛ الإطفاء الفاشل rollback ظاهر
   (يعود العنصر + خطأ).
   ★ FE19-5: كلا الاتجاهين في سجل ops؛ الإقرار نسبي للمستغرَق؛ rollback
   الحذف يحترم الأحدث (نية remove أحدث = لا استعادة عمياء)؛ DELETE
   لغائب (404) يُقر. */
export function toggleWish(id) {
  return function (dispatch, getState) {
    const num = Number(id);
    if (!num) return;
    dispatch(wishlistActions.toggle(num));
    const cid = serverCustomerId(getState);
    if (!cid) return;
    const genAtStart = currentGen(getState);
    const on = getState().wishlist.ids.indexOf(num) !== -1;
    const seq = nextWishSeq();
    if (on) {
      dispatch(wishlistActions.addIntended(num));
      dispatch(wishlistActions.wishOpRecorded({ seq: seq, type: "add", id: num, cid: cid, gen: genAtStart }));
    } else {
      dispatch(wishlistActions.wishOpRecorded({ seq: seq, type: "remove", id: num, cid: cid, gen: genAtStart }));
    }
    queueWish(async function () {
      if (!wishOwnerValid(getState, cid, genAtStart)) return;
      try {
        const res = on
          ? await authFetch(ENDPOINTS.wishOf(cid), { method: "POST", body: { productId: num } })
          : await authFetch(ENDPOINTS.wishRemove(cid, num), { method: "DELETE" });
        if (!wishOwnerValid(getState, cid, genAtStart)) return;
        if (res.status === 403 || res.status === 401) return;
        const ackAs = res.ok || (on && res.status === 409) || (!on && res.status === 404);
        if (!ackAs) {
          dispatch(wishlistActions.wishOpFailed([seq]));
          if (!on) rollbackRemoveRespectingNewer(dispatch, getState, num, seq);
          dispatch(wishlistActions.wishErrorSet({ text: mergeErrMsg(wishLang(getState)) }));
        } else {
          const kind = on ? "add" : "remove";
          const seqs = subsumedWishSeqs((getState().wishlist || {}).ops, num, kind, seq);
          if (seqs.indexOf(seq) === -1) seqs.push(seq);
          dispatch(wishlistActions.wishOpsAck({ seqs: seqs, id: num, kind: kind }));
          if (on) dispatch(wishlistActions.wishDirtyDrop(num));
          refreshWishError(dispatch, getState, false, true);
        }
      } catch (e) {
        if (!wishOwnerValid(getState, cid, genAtStart)) return;
        dispatch(wishlistActions.wishOpFailed([seq]));
        if (!on) rollbackRemoveRespectingNewer(dispatch, getState, num, seq);
        dispatch(wishlistActions.wishErrorSet({ text: mergeErrMsg(wishLang(getState)) }));
      }
    });
  };
}

/* حذف صريح مع مرآة فورية للخادم (تُظهر الفشل).
   ★ FE17-F02: الفاشل rollback ظاهر (يعود العنصر + خطأ) — لا حذف
   صامت يُكتشف في المصالحة التالية.
   ★ FE19-5: النية في سجل ops (تبقى failed للسحب التالي)؛ الـrollback يحترم
   أي نية أحدث على العنصر. */
export function removeWish(id) {
  return function (dispatch, getState) {
    const num = Number(id);
    if (!num) return;
    dispatch(wishlistActions.remove(num));
    const cid = serverCustomerId(getState);
    if (!cid) return;
    const genAtStart = currentGen(getState);
    const seq = nextWishSeq();
    dispatch(wishlistActions.wishOpRecorded({ seq: seq, type: "remove", id: num, cid: cid, gen: genAtStart }));
    queueWish(async function () {
      if (!wishOwnerValid(getState, cid, genAtStart)) return;
      try {
        const res = await authFetch(ENDPOINTS.wishRemove(cid, num), { method: "DELETE" });
        if (!wishOwnerValid(getState, cid, genAtStart)) return;
        if (res.status === 403 || res.status === 401) return;
        if (res.ok || res.status === 404) {
          const seqs = subsumedWishSeqs((getState().wishlist || {}).ops, num, "remove", seq);
          if (seqs.indexOf(seq) === -1) seqs.push(seq);
          dispatch(wishlistActions.wishOpsAck({ seqs: seqs, id: num, kind: "remove" }));
          refreshWishError(dispatch, getState, false, true);
        } else {
          dispatch(wishlistActions.wishOpFailed([seq]));
          rollbackRemoveRespectingNewer(dispatch, getState, num, seq);
          dispatch(wishlistActions.wishErrorSet({ text: mergeErrMsg(wishLang(getState)) }));
        }
      } catch (e) {
        if (!wishOwnerValid(getState, cid, genAtStart)) return;
        dispatch(wishlistActions.wishOpFailed([seq]));
        rollbackRemoveRespectingNewer(dispatch, getState, num, seq);
        dispatch(wishlistActions.wishErrorSet({ text: mergeErrMsg(wishLang(getState)) }));
      }
    });
  };
}
