/* ============================================================
   أطياب الجاسم (React) — شريط الفعاليات المتحرك (EventsBanner)

   الموضع: أول عنصر داخل <main> مباشرة بعد الهيدر المثبّت —
   مكانه ثابت لا يتغير أبداً، ويلتصق أسفل الهيدر عند التمرير
   (sticky) فلا يغطّيه أي محتوى (z-index فوق كل شيء عدا الهيدر
   نفسه وقائمته).

   المحتوى: الإعلان (العنوان) + الشروط + المدة المتبقية (أيام/
   ساعات/دقائق/ثوانٍ تتناقص كل ثانية حتى endAt) + تاريخ البداية
   والنهاية — عربي/إنجليزي حسب لغة الواجهة.

   ★ الحركة حلقة لا نهائية بلا بداية ولا نهاية: الجملة تُكرَّر
     بصفّين متطابقين (نصفا المسار) يُقاس طولهما عند التركيب
     ليغطّيا عرض الشاشة دائماً، والإزاحة بمقدار نصفٍ كامل
     (-50%) تعيد نفس المشهد تماماً فلا قفزة ولا فراغ أبداً —
     ما يختفي من جهة يظهر في الجهة الأخرى متصلاً.
     السرعة ثابتة (بكسل/ثانية) على كل الشاشات عبر مدة محسوبة.

   زر ✕ في أقصى اليسار: إغلاق لزيارة واحدة فقط — يُحفظ في
   sessionStorage فيعود الشريط في الزيارة التالية.

   اللون يكسر النمط عمداً (أحمر-برتقالي صارخ على عكس الذهبي/
   الأسود) للفت الانتباه كما طلب المالك.
   ============================================================ */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { fetchActiveEvents, selectVisibleEvents } from "../../redux/slices/eventsSlice.js";
import { runIdle, cancelIdle } from "../../utils/runIdle.js";
import "./EventsBanner.css";

const DISMISS_KEY = "atyab:events:dismissed:v1";
const REFRESH_MS = 5 * 60 * 1000;
/* سرعة الشريط — بكسل في الثانية (ثابتة على كل الشاشات) */
const SPEED_PX_S = 50;

function readDismissed() {
  try {
    const raw = window.sessionStorage.getItem(DISMISS_KEY);
    const arr = raw ? JSON.parse(raw) : [];
    return new Set(Array.isArray(arr) ? arr.map(String) : []);
  } catch (e) {
    return new Set();
  }
}

function pad2(n) {
  return (n < 10 ? "0" : "") + n;
}

/* { label, days, clock } — العدّاد يتناقص حتى endAt، وقبله حتى startAt */
function countdownOf(ev, now, en) {
  const started = now >= ev.startAt || !ev.startAt;
  const target = started ? ev.endAt : ev.startAt;
  let diff = Math.max(0, target - now);
  const days = Math.floor(diff / 86400000);
  diff -= days * 86400000;
  const hh = Math.floor(diff / 3600000);
  diff -= hh * 3600000;
  const mm = Math.floor(diff / 60000);
  const ss = Math.floor((diff - mm * 60000) / 1000);
  const clock = pad2(hh) + ":" + pad2(mm) + ":" + pad2(ss);
  let label;
  if (en) label = started ? "Ends in" : "Starts in";
  else label = started ? "ينتهي خلال" : "يبدأ خلال";
  const dayWord = en ? (days === 1 ? "day" : "days") : days === 1 ? "يوم" : days === 2 ? "يومان" : "أيام";
  return { label: label, days: days, dayWord: dayWord, clock: clock };
}

function fmtDate(ms, en) {
  if (!ms) return "";
  try {
    return new Date(ms).toLocaleDateString(en ? "en-AE" : "ar-AE", {
      year: "numeric",
      month: "long",
      day: "numeric"
    });
  } catch (e) {
    return "";
  }
}

function EventStrip(props) {
  const ev = props.ev;
  const en = props.en;
  const now = props.now;
  const onDismiss = props.onDismiss;

  const containerRef = useRef(null);
  const unitRef = useRef(null);
  const [repeats, setRepeats] = useState(4);
  const [duration, setDuration] = useState(30);

  const title = (en ? ev.titleEn || ev.titleAr : ev.titleAr || ev.titleEn) || (en ? "Special event" : "فعالية مميزة");
  const terms = en ? ev.termsEn || ev.termsAr : ev.termsAr || ev.termsEn;
  const cd = countdownOf(ev, now, en);
  const range =
    ev.startAt && ev.endAt
      ? en
        ? "From " + fmtDate(ev.startAt, true) + " to " + fmtDate(ev.endAt, true)
        : "من " + fmtDate(ev.startAt, false) + " إلى " + fmtDate(ev.endAt, false)
      : "";

  /* الجملة الواحدة — تُكرَّر داخل كل نصف، والنصفان متطابقان */
  const sentence =
    "✦ " +
    title +
    (terms ? " — " + terms : "") +
    " — " +
    cd.label +
    ": " +
    (cd.days > 0 ? cd.days + " " + cd.dayWord + " " : "") +
    cd.clock +
    (range ? " (" + range + ")" : "") +
    "   ";

  /* ★ القياس: تكرارات تكفي لتغطية عرض الحاوية + واحدة احتياط،
     والمدة = عرض النصف ÷ السرعة — فيُضمن: لا فراغ أبداً،
     وسرعة قراءة واحدة على الجوال والشاشات العريضة. */
  const measure = useCallback(
    function () {
      try {
        const c = containerRef.current;
        const u = unitRef.current;
        if (!c || !u) return;
        const cw = c.clientWidth || 0;
        const uw = (u.getBoundingClientRect && u.getBoundingClientRect().width) || u.offsetWidth || 0;
        if (cw <= 0 || uw <= 0) return;
        let need = Math.ceil(cw / uw) + 1;
        if (need < 2) need = 2;
        if (need > 40) need = 40;
        setRepeats(need);
        const half = uw * need;
        setDuration(Math.max(8, half / SPEED_PX_S));
      } catch (e) {
        /* قياس غير متاح — القيم الافتراضية تكفي */
      }
    },
    []
  );

  useEffect(
    function () {
      measure();
      try {
        if (document.fonts && document.fonts.ready) {
          let alive = true;
          document.fonts.ready.then(function () {
            if (alive) measure();
          });
          var cleanupFonts = function () {
            alive = false;
          };
        }
      } catch (e) {
        /* بلا واجهة خطوط */
      }
      let t = 0;
      function onResize() {
        window.clearTimeout(t);
        t = window.setTimeout(measure, 200);
      }
      window.addEventListener("resize", onResize);
      return function () {
        window.removeEventListener("resize", onResize);
        window.clearTimeout(t);
        if (typeof cleanupFonts === "function") cleanupFonts();
      };
    },
    [measure, ev.id, en]
  );

  /* نص النصف الواحد: الجملة مكررة — النصفان متطابقان حرفياً */
  let halfText = "";
  for (let i = 0; i < repeats; i++) halfText += sentence;

  return (
    <section ref={containerRef} className="events-banner" dir={en ? "ltr" : "rtl"} aria-label={title}>
      {/* وحدة قياس خفية بنفس الخط والحجم تماماً */}
      <span ref={unitRef} className="events-unit" aria-hidden="true">
        {sentence}
      </span>
      <div
        className="events-track"
        style={{ animationDuration: duration + "s", animationName: en ? "events-slide-ltr" : "events-slide-rtl" }}
        aria-hidden="true"
      >
        <span className="events-half">{halfText}</span>
        <span className="events-half">{halfText}</span>
      </div>
      {/* نص ثابت لقارئ الشاشة (المتحرك مُخفي عنه) */}
      <span className="events-sr">{sentence}</span>
      <button type="button" className="events-close" onClick={function () { onDismiss(ev.id); }} aria-label={en ? "Dismiss announcement" : "إغلاق الإعلان"}>
        ✕
      </button>
    </section>
  );
}

export default function EventsBanner() {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) { return s.ui.language; });
  const items = useAppSelector(function (s) { return (s.events && s.events.items) || []; });
  const [now, setNow] = useState(function () { return Date.now(); });
  const [dismissed, setDismissed] = useState(readDismissed);

  /* الجلب عند التركيب + تحديث دوري خفيف.
     ★ جولة 2: الجلبة الأولى تُؤجَّل لخمول المتصفح — الشريط لا يظهر إلا
     بوجود فعالية، ولا يلزم أول رسم. التحديث الدوري يبقى كما هو. */
  useEffect(
    function () {
      const h = runIdle(function () { dispatch(fetchActiveEvents()); });
      const id = window.setInterval(function () {
        dispatch(fetchActiveEvents());
      }, REFRESH_MS);
      return function () {
        cancelIdle(h);
        window.clearInterval(id);
      };
    },
    [dispatch]
  );

  const visible = useMemo(
    function () {
      return selectVisibleEvents({ events: { items: items } }, now).filter(function (e) {
        return !dismissed.has(String(e.id));
      });
    },
    [items, now, dismissed]
  );

  /* تيك العدّاد — يعمل فقط والشريط ظاهر */
  useEffect(
    function () {
      if (!visible.length) return undefined;
      const id = window.setInterval(function () {
        setNow(Date.now());
      }, 1000);
      return function () {
        window.clearInterval(id);
      };
    },
    [visible.length]
  );

  if (!visible.length) return null;
  const en = language === "en";

  function handleDismiss(id) {
    const next = new Set(dismissed);
    next.add(String(id));
    setDismissed(next);
    try {
      window.sessionStorage.setItem(DISMISS_KEY, JSON.stringify(Array.from(next)));
    } catch (e) {
      /* تخزين غير متاح — الإغلاق للعرض الحالي فقط */
    }
  }

  return (
    <>
      {visible.map(function (ev) {
        return <EventStrip key={String(ev.id)} ev={ev} en={en} now={now} onDismiss={handleDismiss} />;
      })}
    </>
  );
}
