/* ============================================================
   أطياب الجاسم (React) — عميل الدفع (PayTabs — صفحة مستضافة)

   عقد v36 (المرجع docs/API-PAYMENTS-CONTRACT-v36.md — بلا /session نهائياً):
     · إنشاء الطلب أولاً: POST /api/orders/{id}
       ← { locationId, deliveryMethodId, paymentMethodId,
           couponCode?, customerNote?, termsAccepted:true }
       → { orderId, invoiceNumber, ...فاتورة الخادم } (الطريقة إلكترونية).
       invoiceNumber هو مرجع مسار الدفع (cartId) — يُحفظ فوراً مع الهوية.
     · سياسة الدفع الوحيدة: GET /api/payments/{id}/status?cartId={invoiceNumber}
       → { status, orderId, invoiceNumber, grandTotal, tranRef, orderStatus,
           paymentStatus, reason, resumable, resumeTranRef, canRetry,
           attemptsUsed/maxAttempts, retryAfterSeconds, ... } —
       يُتحقق من مطابقة orderId قبل أي Start. reason المنظم (لا العربية)
       يحدد الإجراء؛ canRetry إذن تحصيل جديد فقط؛ resumable يسترجع الصفحة
       نفسها عبر Start (resumed=true) حتى مع الاستنفاد/النافذة.
     · بدء الدفع: POST /api/payments/{id}/start ← { orderId }
       → { paymentUrl, tranRef, cartId, resumed, reason: created|resumed, ... }
       ثم توجيه كامل للمتصفح إلى paymentUrl. مهلة الواجهة 60s (v36 §3).
     · صفحة العودة: تُستطلع الحالة كل ~3 ثوانٍ حتى ~60 ثانية. 409 بعد الدفع تعني غالباً
       أن الـcallback سوّاها — يُعاد قراءة تفاصيل الطلب.
     · مُتقاعَد — ممنوع: POST .../session،
       GET .../attempts/{merchantReference}، POST .../confirm.
     · بارامتر الرابط للعرض فقط (?cartId=) — الحُكم من الـ status حصراً.
       لا paymentUrl مرتين لنفس الطلب: عند إغلاق التبويب يُستعلَم
       status أولاً، ولا start جديد إلا بإذن خادمي (reason/resumable).
   ============================================================ */

import { ENDPOINTS, apiError } from "../redux/api.js";
import { authFetch } from "./auth.js";

const PENDING_KEY = "atyab:pendingPayment";

async function readJson(res) {
  const text = await res.text().catch(function () { return ""; });
  if (!text) return null;
  try { return JSON.parse(text); } catch (e) { return null; }
}

function throwPay(res, payload) {
  const d = payload || {};
  /* ★ detail العربية أولاً — مغلّف الخطأ الموحّد (§0) */
  const msg = (d.detail || d.message || d.title) || ("استجابة الخادم: " + res.status);
  const err = apiError(msg, res.status);
  err.response = { status: res.status, data: payload };
  throw err;
}

/* ---------- الاستعلام الوحيد لصفحة العودة ---------- */

/* بدء الدفع لطلب قائم: POST /api/payments/{id}/start ← { orderId }
   → { paymentUrl, tranRef, cartId } — المسار الوحيد للدفع. */
export async function startServerPayment(customerId, orderId, opts) {
  const o = opts || {};
  const budget = Number(o.timeoutMs) > 0 ? Number(o.timeoutMs) : PAYMENT_START_TIMEOUT_MS;
  const res = await authFetch(ENDPOINTS.paymentStart(customerId), {
    method: "POST",
    body: { orderId: Number(orderId) },
    timeoutMs: budget
  });
  const payload = await readJson(res);
  if (!res.ok) throwPay(res, payload);
  return payload || {};
}

export async function getPaymentStatus(customerId, cartId, opts) {
  const o = opts || {};
  const q = { method: "GET" };
  if (Number(o.timeoutMs) > 0) q.timeoutMs = Number(o.timeoutMs);
  const res = await authFetch(
    ENDPOINTS.paymentStatus(customerId) + "?cartId=" + encodeURIComponent(String(cartId || "")),
    q
  );
  const payload = await readJson(res);
  if (!res.ok) throwPay(res, payload);
  return payload || {};
}

/* دفعة معلّقة — cartId هو المرجع الأول (§10)، وtranRef/orderId احتياط */
export function savePendingPayment(p) {
  try {
    window.localStorage.setItem(PENDING_KEY, JSON.stringify(p || {}));
  } catch (e) {}
}
export function readPendingPayment() {
  try {
    const raw = window.localStorage.getItem(PENDING_KEY);
    const o = raw ? JSON.parse(raw) : null;
    return o && typeof o === "object" ? o : null;
  } catch (e) {
    return null;
  }
}

export function clearPendingPayment() {
  try {
    window.localStorage.removeItem(PENDING_KEY);
  } catch (e) {}
}

/* ★ FE32: فصل ربط طلب ميت عن عملية الشراء النشطة (خالصة) — تُسقط orderId
   والمراجع (invoiceNo/cartId/serverId) والعدّادات والحالة الميتة، وتُبقي
   المالك والطريقة والحقول والعميل والإحالة الملزمة كما هي. السلة والمفضلة
   وسجلّ الطلبات ليست جزءاً من الإعداد فلا تُمسّ أبداً. */
export function stripDeadOrderRefs(setup, orderId, deadKind) {
  const cur = (setup && typeof setup === "object") ? setup : {};
  const oid = Number(orderId) || 0;
  if (!oid || Number(cur.orderId) !== oid) return null;
  const next = Object.assign({}, cur);
  try { delete next.orderId; } catch (e) {}
  try { delete next.invoiceNo; } catch (e2) {}
  try { delete next.cartId; } catch (e3) {}
  try { delete next.serverId; } catch (e4) {}
  next.sentCount = 0;
  next.respondedCount = 0;
  next.lastSentAt = 0;
  next.lastResponseAt = 0;
  next.rejectedAt = 0;
  next.unknownAt = 0;
  try { delete next.sentKey; } catch (e5) {}
  try { delete next.lastRejection; } catch (e6) {}
  try { delete next.lastResponseKind; } catch (e7) {}
  next.state = "cancelled";
  next.cancelledAt = Date.now();
  next.deadKind = String(deadKind || "cancelled");
  next.deadOrderId = oid;
  return next;
}

/* ★ FE32: فصل طلب ميت متحقق خادمياً (ملغى/منتهٍ/مدفوع) عن العملية النشطة —
   الإعداد المرتبط به + الدفعة المعلقة لنفس الطلب فقط. تُستدعى بعد تحقق
   خادمي صريح فقط (لا تخمين محلي)، وقبل عرض أي زر استئناف. */
export function detachDeadOrderBinding(orderId, deadKind) {
  try {
    const oid = Number(orderId) || 0;
    if (!oid) return null;
    const cur = readPaymentSetup();
    if (cur && Number(cur.orderId) === oid) {
      const next = stripDeadOrderRefs(cur, oid, deadKind);
      if (next) savePaymentSetup(next);
    }
    try {
      const pp = readPendingPayment();
      if (pp && Number(pp.orderId) === oid) {
        const keep = Object.assign({}, pp);
        try { delete keep.orderId; } catch (e) {}
        try { delete keep.cartId; } catch (e2) {}
        try { delete keep.paymentUrl; } catch (e3) {}
        try { delete keep.tranRef; } catch (e4) {}
        try { delete keep.attemptNo; } catch (e5) {}
        savePendingPayment(keep);
      }
    } catch (eP) {}
    return readPaymentSetup();
  } catch (e) { return null; }
}

/* ---------- إعداد الدفع الموجّه (صفحة الانتظار الوسيطة) ----------
   Checkout تحفظ هنا حقول إنشاء الطلب + الطريقة + العميل، ثم تنتقل
   إلى #/payment/start التي تنشئ الطلب ثم تبدأ الدفع وتغادر إلى PayTabs.
   localStorage (لا state التنقل وحده) حتى تنجو من التحديث. */
const SETUP_KEY = "atyab:paymentSetup";

export function savePaymentSetup(s) {
  try {
    window.localStorage.setItem(SETUP_KEY, JSON.stringify(s || {}));
  } catch (e) {
    return false;
  }
  /* ★ تحقق بالقراءة الراجعة — الفشل (تصفح خاص/امتلاء) يُبلَّغ للمستدعي
     بدل الابتلاع: يعرض تحذير «لا تحدّث الصفحة» ويكمل بالذاكرة. */
  try {
    const raw = window.localStorage.getItem(SETUP_KEY);
    if (!raw) return false;
    const o = JSON.parse(raw);
    return !!(o && typeof o === "object" && String(o.purchaseId || "") === String((s && s.purchaseId) || ""));
  } catch (e) {
    return false;
  }
}

export function readPaymentSetup() {
  try {
    const raw = window.localStorage.getItem(SETUP_KEY);
    const o = raw ? JSON.parse(raw) : null;
    return o && typeof o === "object" ? o : null;
  } catch (e) {
    return null;
  }
}

export function clearPaymentSetup() {
  try {
    window.localStorage.removeItem(SETUP_KEY);
  } catch (e) {}
}

/* ★ F3: إعداد/معلق كل مالك يُحفظ في مخبئه — لا يُفقد عند العودة إليه،
   ولا يُنفَّذ بهوية مختلفة. المفتاح النشط يخص المالك الحالي فقط. */
function setupKeyFor(owner) {
  return owner == null ? SETUP_KEY : SETUP_KEY + ":" + String(Number(owner));
}
function pendingKeyFor(owner) {
  return owner == null ? PENDING_KEY : PENDING_KEY + ":" + String(Number(owner));
}
export function stashSetupForOwner(prevOwner) {
  try {
    if (prevOwner == null) return;
    const raw = window.localStorage.getItem(SETUP_KEY);
    if (!raw) return;
    const o = JSON.parse(raw);
    if (!o || typeof o !== "object") return;
    if (o.customerId && Number(o.customerId) !== Number(prevOwner)) return;
    window.localStorage.setItem(setupKeyFor(prevOwner), raw);
  } catch (e) {}
}
export function restoreSetupForOwner(newOwner) {
  try {
    if (newOwner == null) return null;
    const raw = window.localStorage.getItem(setupKeyFor(newOwner));
    if (!raw) return null;
    const o = JSON.parse(raw);
    if (!o || typeof o !== "object") return null;
    window.localStorage.setItem(SETUP_KEY, raw);
    return o;
  } catch (e) { return null; }
}
export function stashPendingForOwner(prevOwner) {
  try {
    if (prevOwner == null) return;
    const raw = window.localStorage.getItem(PENDING_KEY);
    if (!raw) return;
    const o = JSON.parse(raw);
    if (!o || typeof o !== "object") return;
    if (o.customerId && Number(o.customerId) !== Number(prevOwner)) return;
    window.localStorage.setItem(pendingKeyFor(prevOwner), raw);
  } catch (e) {}
}
export function restorePendingForOwner(newOwner) {
  try {
    if (newOwner == null) return null;
    const raw = window.localStorage.getItem(pendingKeyFor(newOwner));
    if (!raw) return null;
    const o = JSON.parse(raw);
    if (!o || typeof o !== "object") return null;
    window.localStorage.setItem(PENDING_KEY, raw);
    return o;
  } catch (e) { return null; }
}
/* ★ F5: دورة عملية COD — new | in-flight | unknown | done.
   done تُحفظ برقم الطلب ولا تُعاد أبداً لشراء جديد (مفتاح جديد إجباري).
   unknown/missing-response تُبقي المفتاح نفسه للاستئناف (لا طلب آخر). */
export function markSetupDone(orderId, invoiceNo, serverId) {
  try {
    const cur = readPaymentSetup() || {};
    const next = Object.assign({}, cur, {
      orderId: orderId != null ? Number(orderId) : (cur.orderId != null ? Number(cur.orderId) : null),
      invoiceNo: invoiceNo != null ? String(invoiceNo) : (cur.invoiceNo || ""),
      serverId: serverId != null ? Number(serverId) : (cur.serverId != null ? Number(cur.serverId) : null),
      done: true,
      state: "done",
      completedAt: Date.now()
    });
    savePaymentSetup(next);
    /* انسخ للمخبأ المالك أيضاً حتى لا يضيع عند التبديل */
    try {
      if (next.customerId != null) window.localStorage.setItem(setupKeyFor(Number(next.customerId)), JSON.stringify(next));
    } catch (e) {}
    return next;
  } catch (e) { return null; }
}
/* FE27: تعليم العملية كميتة (طلب ملغى/غير قابل للدفع) — لا استئناف برقمها
   ولا بدء تلقائي بعدها؛ الشراء الجديد الصريح يبني هوية جديدة عبر
   freshSetupAfterCancelled. حارس الهوية كالمعتاد. */
export function markSetupCancelled(onlyPurchaseId) {
  try {
    const cur = readPaymentSetup() || {};
    if (cur.done === true || cur.state === "done") return cur;
    if (onlyPurchaseId && cur.purchaseId && String(cur.purchaseId) !== String(onlyPurchaseId)) return cur;
    const sent = (Number(cur.sentCount || 0) || 0);
    const next = Object.assign({}, cur, {
      respondedCount: sent,
      lastResponseKind: "cancelled",
      lastResponseAt: Date.now(),
      state: "cancelled",
      cancelledAt: Date.now()
    });
    savePaymentSetup(next);
    return next;
  } catch (e) { return null; }
}

export function markSetupUnknown(onlyPurchaseId) {
  try {
    const cur = readPaymentSetup() || {};
    if (cur.done) return cur;
    /* ★ FE25-R32-02: حارس الهوية — استجابة عملية أحدث (K2) وصلت أثناء
       انتظار K1؟ لا تُعلِّم إعداد K2 بالمجهول نيابة عن K1. بلا معامل =
       السلوك القديم (للتوافق). */
    if (onlyPurchaseId && cur.purchaseId && String(cur.purchaseId) !== String(onlyPurchaseId)) return cur;
    const next = Object.assign({}, cur, { state: "unknown", unknownAt: Date.now() });
    savePaymentSetup(next);
    return next;
  } catch (e) { return null; }
}

/* ★ FE25-R32-02: عدّادا الإرسال/الاستجابة لربط الرفض بالعملية —
   sentCount يزيد عند كل إرسال فعلي، وrespondedCount يلحق به عند كل رد
   محلول (نوع الرد في lastResponseKind). مجهول = أُرسل بلا رد مسجّل
   (انقطاع/تحطم/timeout/503) فيُصالَح بنفس المفتاح ولا يُفترع بديل.
   القواعد: لا كتابة فوق هوية أحدث (حارس purchaseId)، ولا إحياء done. */
export function markSetupSent(purchaseId) {
  try {
    const cur = readPaymentSetup() || {};
    if (cur.done === true || cur.state === "done") return cur;
    if (purchaseId && cur.purchaseId && String(cur.purchaseId) !== String(purchaseId)) return null;
    const next = Object.assign({}, cur, {
      state: "in-flight",
      sentKey: cur.idempotencyKey ? String(cur.idempotencyKey) : (cur.sentKey || ""),
      sentCount: (Number(cur.sentCount || 0) || 0) + 1,
      lastSentAt: Date.now()
    });
    savePaymentSetup(next);
    return next;
  } catch (e) { return null; }
}

/* ★ رد محلول عام (فشل مُصنَّف بردّ: مخزون/كوبون/عرض/409...) — يلحق
   respondedCount بالمُرسل فلا تُحسب العملية مجهولة. ليس رفض إحالة
   (تلك لها markSetupRejected أدناه). */
export function markSetupResponded(purchaseId) {
  try {
    const cur = readPaymentSetup() || {};
    if (cur.done === true || cur.state === "done") return cur;
    if (purchaseId && cur.purchaseId && String(cur.purchaseId) !== String(purchaseId)) return null;
    const sent = (Number(cur.sentCount || 0) || 0);
    const next = Object.assign({}, cur, {
      respondedCount: sent,
      lastResponseKind: "failed",
      lastResponseAt: Date.now()
    });
    savePaymentSetup(next);
    return next;
  } catch (e) { return null; }
}

/* ★ رفض إحالة قطعي محلول — كالعام أعلاه + state=rejected مع نوع الرفض
   (lastRejection) لمنحه لاحقاً كبوابة وحيدة للعملية البديلة بلا إحالة.
   يُستدعى فقط بعد تصنيف رموز الإحالة الأربعة (لا لكل 400/409). */
export function markSetupRejected(purchaseId, rejectionKind) {
  try {
    const cur = readPaymentSetup() || {};
    if (cur.done === true || cur.state === "done") return cur;
    if (purchaseId && cur.purchaseId && String(cur.purchaseId) !== String(purchaseId)) return null;
    const sent = (Number(cur.sentCount || 0) || 0);
    const next = Object.assign({}, cur, {
      respondedCount: sent,
      lastResponseKind: "referral-rejected",
      lastResponseAt: Date.now(),
      state: "rejected",
      lastRejection: String(rejectionKind || ""),
      rejectedAt: Date.now()
    });
    savePaymentSetup(next);
    return next;
  } catch (e) { return null; }
}

/* FE30: مهلة بدء الدفع الوحيدة (عقد v36 §3 — البنود مرتبة: 10s مزود <
   50s طلب Start < 60s انتظار الواجهة؛ قاعدة 25s ملغاة).
   تُمرَّر لـauthFetch عبر startServerPayment فقط — دون رفع مهلة كل API.
   بلا طبقة تغليف ثانية: النداء الواحد = المهلة الواحدة. تجاوزها ≠ فشل —
   المسار مجهول → تحقق من الحالة، بلا طلب/تحصيل جديد تلقائي. */
export var PAYMENT_START_TIMEOUT_MS = 60000;
/* ---------- هوية عملية الشراء + مفتاح منع التكرار (Idempotency) ----------
   العقد المشترك مع الباك (FRONTEND_CONTRACT §11 — التفصيل في
   backend-msg-round51):
   · كل عملية شراء جديدة = purchaseId + idempotencyKey فريدين، يُحفظان
     في إعداد الدفع مع صاحبهما (customerId) وحقول الإنشاء.
   · يُرسل المفتاح ترويسة `Idempotency-Key` في POST /api/orders/{id}
     (إلكتروني وCOD) — ويُعاد استعمال المفتاح نفسه عند timeout وإعادة
     الإرسال وإعادة تحميل الصفحة والتبويب الثاني: الخادم يرد بالطلب
     نفسه بدل التكرار.
   · مفتاح جديد فقط لعملية جديدة صريحة: تغيّرت المدخلات المؤثرة
     (locationId/deliveryMethodId/paymentMethodId/couponCode) أو بدأ
     المستخدم شراءً جديداً بعد نجاح/إلغاء صريح. مجهولية النتيجة
     (timeout بلا رد) ≠ فشل — ممنوع مفتاح جديد تلقائياً.
   · 409 بأسباب IDEMPOTENCY_* يصنّفها classifyOrderConflict في
     api/orders.js (قيد التنفيذ / مفتاح لمدخلات مختلفة). */

function randomHex(n) {
  let s = "";
  const abc = "0123456789abcdef";
  try {
    const buf = new Uint32Array(n);
    if (window.crypto && window.crypto.getRandomValues) {
      window.crypto.getRandomValues(buf);
      for (let i = 0; i < n; i++) s += abc[buf[i] % 16];
      return s;
    }
  } catch (e) {}
  for (let i = 0; i < n; i++) s += abc[Math.floor(Math.random() * 16)];
  return s;
}

export function newPurchaseIdentity() {
  return {
    purchaseId: "p_" + Date.now().toString(36) + "_" + randomHex(8),
    idempotencyKey: "atyab-" + Date.now().toString(36) + "-" + randomHex(12)
  };
}

/* ★ #2+#3: البصمة المؤثرة لحقول الإنشاء — أي تغيير فيها = عملية جديدة صريحة.
   العرض مفرد OfferId (عقد الخادم) — تغييره = مدخلات جديدة = مفتاح جديد.
   تغيير المدخلات مع الاحتفاظ بنفس المفتاح يسبب تعارضاً خلفياً — ممنوع. */
export function singleOfferOf(f) {
  const o = f || {};
  if (o.OfferId != null && Number(o.OfferId)) return Number(o.OfferId);
  if (o.offerId != null && Number(o.offerId)) return Number(o.offerId);
  if (Array.isArray(o.offerIds) && o.offerIds.length) return Number(o.offerIds[0]) || 0;
  return 0;
}
export function canonicalOrderFields(f) {
  const o = f || {};
  return [o.locationId || "", o.deliveryMethodId || "", o.paymentMethodId || "", o.couponCode || "", o.customerNote || "", String(singleOfferOf(o) || "")].join("|");
}

/* ★ FE27: رفض إعادة البدء — رموز منظمة فقط (code/reason). الرفض الصريح
   يعني: لا Start جديد ولا إنشاء طلب بديل تلقائياً — رسالة توجيه لـ«طلباتي».
   ★ FE30: رموز v36 (RFC7807 title — انظر عقد v36 §1): max_attempts_reached ≡
   attempts_exhausted، + order_expired + order_not_payable + refund_review_open. */
const RETRY_REJECT_TOKENS = ["retry_rejected", "retry_not_allowed", "order_cancelled", "order_closed", "attempt_limit_reached", "max_attempts_reached", "attempts_exhausted", "order_expired", "order_not_payable", "refund_review_open"];
export function classifyRetryReject(data, status) {
  const d = data || {};
  const fields = [d.code, d.reason, d.errorCode, d.error_code];
  for (let i = 0; i < fields.length; i++) {
    const v = String(fields[i] || "").trim().toLowerCase();
    if (v && RETRY_REJECT_TOKENS.indexOf(v) !== -1) return v;
  }
  return null;
}

/* ★ #3: هوية الإعداد — تُحفظ لكل طرق الدفع وتُعاد عند المجهول/التحديث.
   نفس الحقول والمالك = نفس المفتاح. طلب قائم (orderId) يُستأنف برقمه
   وبمفتاحه دائماً — لا عملية جديدة ولا مفتاح جديد لطلب مولود. */
export function ensureSetupIdentity(prevSetup, customerId, orderFields) {
  const p = prevSetup && typeof prevSetup === "object" ? prevSetup : null;
  const canon = canonicalOrderFields(orderFields);
  if (
    p && p.purchaseId && p.idempotencyKey &&
    Number(p.customerId) === Number(customerId) &&
    !p.done && p.state !== "done" && p.state !== "cancelled" &&
    String(p.fieldsCanon || "") === canon
  ) {
    /* ★ orderId سابق بنفس الحقول = استئناف (Start فقط) — لا مفتاح جديد */
    const out = { purchaseId: String(p.purchaseId), idempotencyKey: String(p.idempotencyKey), reused: true };
    out.fieldsCanon = canon;
    if (p.orderId) out.orderId = Number(p.orderId);
    return out;
  }
  const ni = newPurchaseIdentity();
  ni.reused = false;
  ni.fieldsCanon = canon;
  return ni;
}
