/* الدولة بالمفتاح — null إن لم توجد */
function countryByKey(key) {
  const k = String(key == null ? "" : key).trim();
  for (let i = 0; i < COUNTRIES.length; i++) {
    if (COUNTRIES[i].key === k) return COUNTRIES[i];
  }
  return null;
}

/* مدن دولة بصيغة خيارات {key: الاسم العربي (يُحفظ)، label: بلغة الواجهة} */
function citiesOfCountry(key, lang) {
  const c = countryByKey(key);
  return ((c && c.cities) || []).map(function (m) {
    return { key: m.ar, label: lang === "en" ? m.en || m.ar : m.ar };
  });
}

/* توحيد قيمة region قديمة (اسم مدينة/دولة أو مفتاح) إلى مفتاح دولة.
   القيم المجهولة ← "AE" (الافتراضي الإماراتي). */
function normalizeRegionKey(value) {
  const s = String(value == null ? "" : value).trim();
  if (!s) return "AE";
  for (let i = 0; i < COUNTRIES.length; i++) {
    const c = COUNTRIES[i];
    if (s === c.key || s === c.label || s === c.short || s === c.labelEn || s === c.shortEn) return c.key;
    for (let j = 0; j < c.cities.length; j++) {
      if (s === c.cities[j].ar || s === c.cities[j].en) return c.key;
    }
  }
  return "AE";
}

