/* ============================================================
   أطياب الجاسم (React) — دورة أقسام التسوّق (promoCycle)

   مصدر واحد لترتيب التنقّل الدائري بين الأقسام الأربعة:
     العطور ← البخور ← دهن العود ← العروض ← (عودة للعطور)

   · nextPromo(page): القسم التالي — لزر الهيدر الذهبي.
   · prevPromo(page): القسم السابق — للزر الذهبي أسفل القوائم.
   · صفحة خارج الدورة (الرئيسية وغيرها) ← الافتراضي: التالي = العطور.
   ============================================================ */

export const PROMO_CYCLE = [
  { page: "perfumes", label: "العطور", labelEn: "Perfumes" },
  { page: "incense", label: "البخور", labelEn: "Bakhour" },
  { page: "ouds", label: "دهن العود", labelEn: "Oud Oils" },
  { page: "offers", label: "العروض", labelEn: "Offers" }
];

export function cycleIndexOf(page) {
  for (let i = 0; i < PROMO_CYCLE.length; i++) {
    if (PROMO_CYCLE[i].page === page) return i;
  }
  return -1;
}

/* التالي في الدورة — زر الهيدر */
export function nextPromo(page) {
  const i = cycleIndexOf(page);
  if (i === -1) return PROMO_CYCLE[0];
  return PROMO_CYCLE[(i + 1) % PROMO_CYCLE.length];
}

/* السابق في الدورة — الزر أسفل القوائم */
export function prevPromo(page) {
  const i = cycleIndexOf(page);
  if (i === -1) return PROMO_CYCLE[PROMO_CYCLE.length - 1];
  return PROMO_CYCLE[(i - 1 + PROMO_CYCLE.length) % PROMO_CYCLE.length];
}
