/* حماية من أي بيئة بلا localStorage (تصفّح خاص/متصفّح مقيّد) */
function ls() {
  try {
    return window.localStorage || null;
  } catch (e) {
    return null;
  }
}

export function readRaw(key, fallback) {
  const store = ls();
  if (!store) return fallback == null ? "" : fallback;
  try {
    const v = store.getItem(key);
    return v == null ? (fallback == null ? "" : fallback) : v;
  } catch (e) {
    return fallback == null ? "" : fallback;
  }
}

export function writeRaw(key, value) {
  const store = ls();
  if (!store) return;
  try {
    store.setItem(key, String(value));
  } catch (e) {
    /* متصفّح بلا تخزين — نتجاهل بهدوء */
  }
}

export function removeRaw(key) {
  const store = ls();
  if (!store) return;
  try {
    store.removeItem(key);
  } catch (e) {
    /* تجاهل */
  }
}

export function readJSON(key, fallback) {
  const raw = readRaw(key, "");
  if (!raw) return fallback;
  try {
    const value = JSON.parse(raw);
    return value == null ? fallback : value;
  } catch (e) {
    return fallback;
  }
}

export function writeJSON(key, value) {
  try {
    writeRaw(key, JSON.stringify(value));
  } catch (e) {
    /* قيمة غير قابلة للتحويل — نتجاهل */
  }
}

/* قراءة نصية محصورة بين قيمتين (تُستخدم للوضع واللغة) */
export function readEnum(key, allowed, fallback) {
  const raw = readRaw(key, "");
  return allowed.indexOf(raw) !== -1 ? raw : fallback;
}
