/* ============================================================
   أطياب الجاسم — Redux slice لكشف مستحقات المسوّق
   يُحمَّل عند دخول الرابط فقط (الصفحة ترسله مع الكود من المسار).
   التسجيل في الـ store (مرة واحدة):
     import marketerStatementReducer from "./slices/marketerStatementSlice.js";
     // reducers: { ..., marketerStatement: marketerStatementReducer }
   ملاحظة: kind يُمرَّر عبر rejectWithValue لأن action.error لا يحمل
   خصائص مخصصة بعد التسلسل.
   ============================================================ */
import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import { fetchMarketerStatement } from "../../api/marketers.js";

export const fetchStatement = createAsyncThunk(
  "marketerStatement/fetch",
  async function (code, thunkAPI) {
    try {
      return await fetchMarketerStatement(code, { signal: thunkAPI.signal });
    } catch (e) {
      if (e && (e.name === "AbortError" || e.code === "EABORTED")) throw e;
      return thunkAPI.rejectWithValue({ kind: (e && e.kind) || "unavailable" });
    }
  }
);

const initialState = {
  code: "",
  data: null,
  status: "idle", /* idle | loading | succeeded | failed */
  errorKind: "" /* validation | not_found | forbidden | unavailable | network */
};

const marketerStatementSlice = createSlice({
  name: "marketerStatement",
  initialState: initialState,
  reducers: {
    resetStatement: function () { return Object.assign({}, initialState); }
  },
  extraReducers: function (builder) {
    builder
      .addCase(fetchStatement.pending, function (state, action) {
        state.code = String((action.meta && action.meta.arg) || "");
        state.data = null;
        state.status = "loading";
        state.errorKind = "";
      })
      .addCase(fetchStatement.fulfilled, function (state, action) {
        state.data = action.payload;
        state.status = "succeeded";
        state.errorKind = "";
      })
      .addCase(fetchStatement.rejected, function (state, action) {
        /* الإلغاء (مغادرة الصفحة) ليس خطأ — عودة هادئة للخمول */
        if (action.error && (action.error.name === "AbortError" || action.error.code === "EABORTED")) {
          state.status = "idle";
          state.errorKind = "";
          return;
        }
        state.status = "failed";
        state.errorKind = (action.payload && action.payload.kind) || "unavailable";
      });
  }
});

export const marketerStatementActions = marketerStatementSlice.actions;
export const selectMarketerStatement = function (s) { return s.marketerStatement || initialState; };
export default marketerStatementSlice.reducer;
