/* ============================================================
   أطياب الجاسم — طبقة API لكشف مستحقات المسوّق — v4 (عقد v68)
   GET {API_BASE}/api/marketers/{code}/statement — بلا توكن.
   الكود يُطبَّع أحرفًا كبيرة تلقائيًا. لا تغيير هنا.
   الحقول: countedBase / estimated / influencerId / currencyId /
   returnedGoodsTotal للصفوف، وcountedBaseTotal / returnedGoodsTotal /
   hasEstimates للإجماليات (مع قبول snake_case للتوافق).
   · العرض يقرأ countedBaseTotal كما جاء — بلا تثبيت رقم وبلا اشتقاق
     (لا قسمة عمولة/نسبة). الغياب ← احتياط productsTotal (خادم قديم).
   · الأخطاء: 400 فارغ / 404 غير موجود / 403 موقوف / 503 عطل مؤقت /
     فشل الشبكة أو HTML (404 الاستضافة) ≠ كود خاطئ أبدًا.
   ============================================================ */
import { API_BASE_URL } from "../redux/api.js";

function normCode(code) {
  return String(code == null ? "" : code).replace(/\s+/g, "").toUpperCase();
}

function fail(kind, message, extra) {
  const e = new Error(message || kind);
  e.kind = kind;
  if (extra) e.detail = extra;
  return e;
}

function numOrNull(v) {
  return v == null ? null : Number(v);
}

/* أساس عمولة الصف: countedBase، وإن غاب (خادم قديم) فproductsTotal */
function rowSaleBase(x) {
  if (!x) return 0;
  return x.countedBase != null ? Number(x.countedBase) : Number(x.productsTotal || 0);
}

/* مفتاح عملة الصف — "main" عند غياب currencyId (خادم قديم/عملة واحدة) */
function rowCurrencyKey(x) {
  return x && x.currencyId != null ? String(x.currencyId) : "main";
}

/* إجمالي البيع المعروض: countedBaseTotal، وإن غاب فproductsTotal.
   لا تثبيت أرقام هنا ولا اشتقاق — القراءة من الرد فقط. */
function selectSaleTotal(data) {
  const d = data || {};
  return d.countedBaseTotal != null ? d.countedBaseTotal : (d.productsTotal != null ? d.productsTotal : null);
}

function normalizeStatement(d, fallbackCode) {
  const src = d && typeof d === "object" ? d : {};
  const list = src.rows || src.items || src.data || [];
  const rows = (Array.isArray(list) ? list : []).map(function (x) {
    return {
      orderNo: (x.orderNo != null ? x.orderNo : x.order_no),
      orderCode: (x.orderCode != null ? x.orderCode : x.order_code),
      orderDate: (x.orderDate != null ? x.orderDate : x.order_date),
      productsTotal: Number(x.productsTotal != null ? x.productsTotal : (x.products_total != null ? x.products_total : 0)),
      rate: Number(x.rate != null ? x.rate : 0),
      commission: (x.commission == null ? null : Number(x.commission)),
      counts: !!x.counts,
      countedBase: numOrNull(x.countedBase != null ? x.countedBase : x.counted_base),
      estimated: !!(x.estimated),
      influencerId: (x.influencerId != null ? x.influencerId : (x.influencer_id != null ? x.influencer_id : null)),
      currencyId: (x.currencyId != null ? x.currencyId : (x.currency_id != null ? x.currency_id : null)),
      returnedGoodsTotal: numOrNull(x.returnedGoodsTotal != null ? x.returnedGoodsTotal : x.returned_goods_total)
    };
  });
  return {
    marketerCode: (src.marketerCode || src.marketer_code || src.code || fallbackCode),
    marketerName: (src.marketerName || src.marketer_name || ""),
    isActive: (src.isActive != null ? !!src.isActive : true),
    currentRate: (src.currentRate != null ? Number(src.currentRate) : (src.current_rate != null ? Number(src.current_rate) : null)),
    rows: rows,
    countedOrders: (src.countedOrders != null ? Number(src.countedOrders) : (src.counted_orders != null ? Number(src.counted_orders) : null)),
    productsTotal: (src.productsTotal != null ? Number(src.productsTotal) : (src.products_total != null ? Number(src.products_total) : null)),
    totalDue: (src.totalDue != null ? Number(src.totalDue) : (src.total_due != null ? Number(src.total_due) : null)),
    countedBaseTotal: numOrNull(src.countedBaseTotal != null ? src.countedBaseTotal : src.counted_base_total),
    returnedGoodsTotal: numOrNull(src.returnedGoodsTotal != null ? src.returnedGoodsTotal : src.returned_goods_total),
    hasEstimates: !!((src.hasEstimates != null ? src.hasEstimates : src.has_estimates))
  };
}

function isHtml(text) {
  const t = String(text || "").slice(0, 2000).toLowerCase();
  return t.indexOf("<!doctype") >= 0 || t.indexOf("<html") >= 0 || t.indexOf("github pages") >= 0;
}

export async function fetchMarketerStatement(code, opts) {
  const c = normCode(code);
  if (!c) throw fail("validation", "empty");
  const signal = opts && opts.signal ? opts.signal : undefined;
  const base = String(API_BASE_URL || "").replace(/\/+$/, "");
  const url = base + "/api/marketers/" + encodeURIComponent(c) + "/statement";
  let res;
  try {
    res = await fetch(url, {
      headers: { Accept: "application/json", "ngrok-skip-browser-warning": "true" },
      signal: signal
    });
  } catch (e) {
    if (e && (e.name === "AbortError" || e.code === "EABORTED")) throw e;
    throw fail("network", "network");
  }
  const text = await res.text().catch(function () { return ""; });
  if (isHtml(text)) throw fail("unavailable", "html_response", "http_" + res.status);
  let body = {};
  try { body = text ? JSON.parse(text) : {}; }
  catch (e) { throw fail("unavailable", "bad_json", "http_" + res.status); }
  if (res.status === 404) throw fail("not_found", "not_found");
  if (res.status === 403) throw fail("forbidden", "forbidden");
  if (res.status === 503 || res.status === 502) throw fail("unavailable", "unavailable");
  if (!res.ok) throw fail("unavailable", "http_" + res.status);
  if (body && (body.code === "forbidden" || body.title === "forbidden")) throw fail("forbidden", "forbidden");
  if (body && (body.code === "not_found" || body.title === "not_found")) throw fail("not_found", "not_found");
  return normalizeStatement(body, c);
}

export { normCode, rowSaleBase, rowCurrencyKey, selectSaleTotal };
