import { useState } from "react";
import { Link } from "react-router-dom";
import { pathForPage } from "../../routes.js";
import { ATYAB_PAGES, ATYAB_CONTACT, ATYAB_SOCIAL } from "../../data/appConfig.js";
import { useAppSelector } from "../../redux/hooks.js";
import { selectSupport } from "../../redux/slices/settingsSlice.js";
import { T, t } from "../../i18n.js";
import SmallHeader from "../Headers/SmallHeader.jsx";
import { Icon } from "../Source/Icons.jsx";

/* هدف أي زر — بصيغة مسار راوتر */
function target(key) {
  return pathForPage(key, ATYAB_PAGES);
}

export default function Footer() {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const session = useAppSelector(function (s) {
    return s.user.session;
  });
  const [year] = useState(function () {
    return new Date().getFullYear();
  });

  const isEn = language === "en";
  const accountTo = session ? target("profile") : target("login");
  const support = useAppSelector(selectSupport);
  const C = ATYAB_CONTACT || {};
  const S = ATYAB_SOCIAL || {};
  const addressText = T(C.address, language) || "";

  return (
    <footer id="footer" className="footer">
      {/* ★ شريط الدخول للزوّار فقط — العضو مسجّل ومشترك فلا يظهر له */}
      {session ? null : (
      <div className="footer-login">
        <div className="container">
          <h4>{isEn ? t("en", "footer.login.title", "تسجيل الدخول") : "تسجيل الدخول"}</h4>
          <p>
            {isEn
              ? t("en", "footer.login.text", "")
              : "حسابك جاهز واشتراكك في النشرة قائم — سجّل الدخول لتتابع طلباتك وقائمة رغباتك ونقاطك."}
          </p>
          <Link
            className="login-btn"
            to={accountTo}
            data-page={session ? "profile" : "login"}
          >
            {session ? (isEn ? "My account" : "حسابي") : isEn ? t("en", "footer.login.btn", "Log in") : "تسجيل الدخول"}
          </Link>
        </div>
      </div>
      )}

      <div className="container footer-top">
        <div className="footer-grid">
          <div className="footer-about">
            <Link to={target("home")} className="logo" data-page="home">
              <span className="sitename">
                أطياب الجاسم<small>ATYAB AL-JASEM</small>
              </span>
            </Link>
            <p>
              {isEn
                ? t("en", "footer.about", "")
                : "متجر إماراتي متخصص في العطور الشرقية والبخور الفاخر، نصنع العبق بأنفسنا ونوصله إليك بعناية."}
            </p>
          </div>

          <div className="footer-links">
            <h4>{isEn ? t("en", "footer.services", "خدماتنا") : "خدماتنا"}</h4>
            <ul>
              <li>
                <Link to={target("perfumes")} data-page="perfumes">
                  {isEn ? t("en", "footer.svc.perfumes", "عطور فاخرة") : "عطور فاخرة"}
                </Link>
              </li>
              <li>
                <Link to={target("incense")} data-page="incense">
                  {isEn ? t("en", "footer.svc.custom", "بخور مخصّص") : "بخور مخصّص"}
                </Link>
              </li>
              <li>
                <Link to={target("shippingInfo")} data-page="shippingInfo">
                  {isEn ? t("en", "footer.svc.shipping", "توصيل سريع") : "توصيل سريع"}
                </Link>
              </li>
            </ul>
          </div>

          <div className="footer-about footer-follow">
            <h4>{isEn ? t("en", "footer.follow", "تابعنا") : "تابعنا"}</h4>
            <div className="footer-contact">
              <p>
                <strong>{isEn ? t("en", "footer.address", "العنوان:") : "العنوان:"}</strong>{" "}
                <span>{addressText}</span>
              </p>
              <p>
                <strong>{isEn ? t("en", "footer.phone", "هاتف:") : "هاتف:"}</strong>{" "}
                <span dir="ltr">{support.phone}</span>
              </p>
              <p>
                <strong>{isEn ? t("en", "footer.email", "البريد:") : "البريد:"}</strong>{" "}
                <span>
                  <a href={"mailto:" + support.email}>{support.email}</a>
                </span>
              </p>
            </div>
            <div className="social-links">
              <a href={"https://wa.me/" + support.whatsappDigits} target="_blank" rel="noopener noreferrer" aria-label="WhatsApp">
                <Icon name="whatsapp" />
              </a>
              <a href={S.instagram || "https://www.instagram.com/atyabaljasim"} target="_blank" rel="noopener noreferrer" aria-label="Instagram">
                <Icon name="instagram" />
              </a>
              <a href={S.tiktok || "https://www.tiktok.com/@atyab.al.jasem"} target="_blank" rel="noopener noreferrer" aria-label="TikTok">
                <Icon name="tiktok" />
              </a>
              <a href={S.snapchat || "https://www.snapchat.com/invite/atyabaljasim"} target="_blank" rel="noopener noreferrer" aria-label="Snapchat">
                <Icon name="snapchat" />
              </a>
            </div>
          </div>
        </div>
      </div>

      <div id="infoBarFooter">
        <SmallHeader flat />
      </div>

      <div className="container footer-bottom">
        <p>
          © <span id="footerYear">{year}</span>{" "}
          <span>{isEn ? t("en", "footer.rights", "جميع الحقوق محفوظ") : "جميع الحقوق محفوظ"}</span> —{" "}
          <span className="gold-text sitename">أطياب الجاسم</span>
        </p>
        <p>{isEn ? t("en", "footer.madeIn", "صُنع بعناية في الإمارات") : "صُنع بعناية في الإمارات"}</p>
      </div>
    </footer>
  );
}
