/* ============================================================
   أطياب الجاسم — هيكل التنقل بين الصفحات (RouteSkeleton)

   لماذا؟ حزم الصفحات تُنزَّل عند الزيارة (lazy) فكان الـ fallback
   div فارغاً → شاشة بيضاء 1-2 ثانية. الآن كل مسار يعرض هيكلاً
   يطابق شكل صفحته (شبكة بطاقات/عرض/سلة/دفع/تتبع...) فيُرى التحميل
   فوراً بدل البياض، وبلا قفزة تخطيط (ارتفاع ثابت).

   ★ يُستورد من App.jsx مباشرة (الحزمة الرئيسية) — لذلك هو خفيف:
      يعيد استعمال هياكل Skeletons الجاهزة + CSS خالص بلا صور.
   ★ يقرأ المسار من window.location.hash مباشرة (بلا useLocation)
      حتى يعمل داخل Suspense fallback قبل مطابقة الراوتر.
   ============================================================ */

import CardSkeleton from "./CardSkeleton.jsx";
import OfferSkeleton from "./OfferSkeleton.jsx";
/* ★ جولة 7: بديل الإقلاع للرئيسية نسخة ثابتة من الهيرو (بلا وميض) —
   HomeSkeleton بقي للاستعمال الداخلي فقط إن لزم. */
import HomeBootFallback from "./HomeBootFallback.jsx";
import { StatementSkeleton, TrackSkeleton, ListRowsSkeleton } from "./MiscSkeleton.jsx";
import "./Skeletons.css";

function currentRoute() {
  try {
    const h = String((window.location && window.location.hash) || "");
    const path = h.replace(/^#/, "").split("?")[0];
    return path || "/";
  } catch (e) {
    return "/";
  }
}

/* خطوات الدفع + حقول + ملخص — نفس إيقاع CheckoutPage */
function CheckoutSkeleton() {
  const steps = [0, 1, 2];
  const fields = [0, 1, 2, 3, 4, 5];
  return (
    <div role="status" aria-live="polite" aria-label="جارٍ تحميل صفحة الدفع">
      <div className="sk-row" aria-hidden="true" style={{ marginBottom: "18px" }}>
        {steps.map(function (i) {
          return <span className="sk-block sk-round sk-avatar" key={i} />;
        })}
        <span className="sk-block sk-line" style={{ width: "30%" }} />
      </div>
      <div style={{ display: "grid", gap: "12px" }} aria-hidden="true">
        {fields.map(function (i) {
          return <span className="sk-block sk-field" key={i} />;
        })}
      </div>
      <div className="sk-carrier" aria-hidden="true" style={{ marginTop: "18px" }}>
        <span className="sk-block sk-line" style={{ width: "45%" }} />
        <span className="sk-block sk-line short" />
        <span className="sk-block sk-btn" style={{ width: "55%" }} />
      </div>
    </div>
  );
}

/* صورة المنتج + معلوماته — نفس إيقاع ShowProductDetailsPage */
function ProductSkeleton() {
  return (
    <div role="status" aria-live="polite" aria-label="جارٍ تحميل المنتج">
      <div className="sk-showcase" aria-hidden="true">
        <div className="sk-block" style={{ height: 300 }} />
        <div style={{ display: "grid", gap: 14, alignContent: "start" }}>
          <span className="sk-block sk-line short" />
          <span className="sk-block" style={{ height: 28 }} />
          <span className="sk-block sk-line" />
          <span className="sk-block sk-line short" />
          <span className="sk-block sk-btn" style={{ width: "60%" }} />
        </div>
      </div>
    </div>
  );
}

/* بطاقة دخول/تسجيل في المنتصف */
function AuthSkeleton() {
  return (
    <div role="status" aria-live="polite" aria-label="جارٍ تحميل صفحة الدخول" style={{ maxWidth: "420px", margin: "0 auto" }}>
      <div className="sk-carrier" aria-hidden="true">
        <span className="sk-block sk-line" style={{ width: "55%", height: 22 }} />
        <span className="sk-block sk-field" />
        <span className="sk-block sk-field" />
        <span className="sk-block sk-btn" />
        <span className="sk-block sk-line tiny" style={{ marginInline: "auto" }} />
      </div>
    </div>
  );
}

/* صفحات النصوص (تواصل/عن/شحن/فروع/دفع/قانوني/صيانة) */
function InfoSkeleton() {
  const lines = [0, 1, 2, 3, 4, 5];
  return (
    <div role="status" aria-live="polite" aria-label="جارٍ تحميل الصفحة" style={{ display: "grid", gap: "12px" }}>
      <span className="sk-block" style={{ height: 30, width: "42%" }} aria-hidden="true" />
      {lines.map(function (i) {
        return <span className="sk-block sk-line" key={i} style={{ width: i % 3 === 2 ? "64%" : "100%" }} aria-hidden="true" />;
      })}
      <span className="sk-block sk-btn" style={{ width: "38%" }} aria-hidden="true" />
    </div>
  );
}

/* العربة: صفوف + ملخص — نفس إيقاع TrolleyPage */
function CartSkeleton() {
  const rows = [0, 1, 2];
  return (
    <div role="status" aria-live="polite" aria-label="جارٍ تحميل العربة">
      {rows.map(function (i) {
        return (
          <div className="sk-hrow" key={i} aria-hidden="true">
            <span className="sk-block sk-round sk-avatar" />
            <span style={{ flex: 1, display: "grid", gap: "8px" }}>
              <span className="sk-block sk-line" style={{ width: "38%" }} />
              <span className="sk-block sk-line" style={{ width: "62%" }} />
            </span>
          </div>
        );
      })}
      <div className="sk-carrier" aria-hidden="true">
        <span className="sk-block sk-line" style={{ width: "45%" }} />
        <span className="sk-block sk-line short" />
        <span className="sk-block sk-btn" style={{ width: "55%" }} />
      </div>
    </div>
  );
}

function SkeletonFor(route) {
  const p = String(route || "/");
  const parts = p.split("/").filter(Boolean);
  const first = parts[0] || "";
  if (p === "/") return <HomeBootFallback />;
  if (first === "product") return <ProductSkeleton />;
  if (first === "cart") return <CartSkeleton />;
  if (first === "checkout") return <CheckoutSkeleton />;
  if (first === "tracking" || first === "payment") return <TrackSkeleton />;
  if (first === "m") return <StatementSkeleton />;
  if (first === "profile") return <ListRowsSkeleton count={4} label="جارٍ تحميل الحساب" />;
  if (first === "login" || first === "register") return <AuthSkeleton />;
  if (first === "offers") return <OfferSkeleton count={2} />;
  if (first === "perfumes" || first === "ouds" || first === "incense" || first === "mists" || first === "lotions" || first === "mukhamaria" || first === "hair" || first === "search" || first === "wishlist") {
    return <CardSkeleton count={first === "wishlist" ? 4 : 8} />;
  }
  return <InfoSkeleton />;
}

export function RouteSkeleton(props) {
  const route = (props && props.route) || currentRoute();
  return SkeletonFor(route);
}

/* fallback الـ Suspense في App.jsx — يقرأ الوجهة الجديدة فور التنقل.
   ★ جولة 7: على "/" يُعرض الهيرو الثابت نفسه (بلا حاوية/حشوة إضافية
   حتى يطابق أول رسم تماماً) — لا مربعات رمادية في أول زيارة أبداً. */
export function RouteFallback() {
  const route = currentRoute();
  if (route === "/") return <HomeBootFallback />;
  return (
    <div className="container" style={{ minHeight: "60vh", paddingTop: "24px", paddingBottom: "24px" }}>
      <RouteSkeleton route={route} />
    </div>
  );
}

export default RouteFallback;
