/* ============================================================
   أطياب الجاسم (React) — مخزن Redux (المصدر الواحد للحقيقة)
   كل حالة الموقع هنا: المسار، الكتالوجات، المفضلة، العربة، المستخدم،
   والتقييمات. الكومبوننتات تقرأ منه ولا تُخزّن نسخة خاصة بها.
   مع مُستمع واحد يحفظ ما يجب حفظه في localStorage.
   ============================================================ */

import { configureStore } from "@reduxjs/toolkit";
import { uiReducer } from "./slices/uiSlice.js";
import { catalogReducer } from "./slices/catalogSlice.js";
import perfumesReducer from "./slices/perfumesSlice.js";
import oudsReducer from "./slices/oudsSlice.js";
import incensesReducer from "./slices/incensesSlice.js";
/* ★ R23: شرائح «باقي المنتجات» — نفس المصنع والنمط */
import mistsReducer from "./slices/mistsSlice.js";
import lotionsReducer from "./slices/lotionsSlice.js";
import mukhamariaReducer from "./slices/mukhamariaSlice.js";
import hairReducer from "./slices/hairSlice.js";
import imagesReducer from "./slices/imagesSlice.js";
import { wishlistReducer, cleanWishOps } from "./slices/wishlistSlice.js";
import { cartReducer } from "./slices/cartSlice.js";
import { userReducer } from "./slices/userSlice.js";
import { customerReducer } from "./slices/customerSlice.js";
import { geoReducer } from "./slices/geoSlice.js";
import { reviewsReducer } from "./slices/reviewsSlice.js";
import { ordersReducer } from "./slices/ordersSlice.js";
import { storeInfoReducer } from "./slices/storeInfoSlice.js";
import settingsReducer from "./slices/settingsSlice.js";
import profilesReducer from "./slices/productProfilesSlice.js";
import { offersReducer } from "./slices/offersSlice.js";
import { eventsReducer } from "./slices/eventsSlice.js";
import marketerStatementReducer from "./slices/marketerStatementSlice.js";
import { KEYS, readJSON, writeJSON, writeRaw, removeRaw } from "./persist.js";

export const store = configureStore({
  reducer: {
    ui: uiReducer,
    catalog: catalogReducer,
    perfumes: perfumesReducer,
    ouds: oudsReducer,
    incenses: incensesReducer,
    mists: mistsReducer,
    lotions: lotionsReducer,
    mukhamaria: mukhamariaReducer,
    hair: hairReducer,
    images: imagesReducer,
    wishlist: wishlistReducer,
    cart: cartReducer,
    user: userReducer,
    customer: customerReducer,
    geo: geoReducer,
    reviews: reviewsReducer,
    orders: ordersReducer,
    storeInfo: storeInfoReducer,
    settings: settingsReducer,
    profiles: profilesReducer,
    offers: offersReducer,
    events: eventsReducer,
    marketerStatement: marketerStatementReducer
  },
  middleware: function (getDefault) {
    return getDefault({ serializableCheck: false, immutableCheck: false });
  }
});

/* ------------------------------------------------------------
   الحفظ: نكتب فقط عند تغيّر فعلي (مقارنة نصّية) — فلا كتابة لكل نقرة
   ★ الشرائح تكتب المفضلة/المستخدم/التقييمات/الوضع/اللغة بنفسها،
     وما يتبقّى هنا هو العربة والكوبون.
   ------------------------------------------------------------ */
const last = { cart: "", coupon: "", wishlist: "", wishDirty: "", wishDel: "", wishOps: "", basketOwner: "__init__", wishOwner: "__init__", wishMerged: "" };

function persist() {
  const state = store.getState();
  const cart = JSON.stringify(state.cart.rows);
  if (cart !== last.cart) {
    last.cart = cart;
    writeJSON(KEYS.cart, state.cart.rows);
  }
  /* ★ F3: مالك السلة يُحفظ معها — لا تُفسَّر صفوف A كضيف لاحقاً */
  const bo = state.cart && state.cart.basketOwner != null ? String(Number(state.cart.basketOwner)) : "";
  if (bo !== last.basketOwner) {
    last.basketOwner = bo;
    if (!bo) removeRaw(KEYS.basketOwner);
    else writeJSON(KEYS.basketOwner, Number(bo));
  }
  if (state.cart.coupon !== last.coupon) {
    last.coupon = state.cart.coupon;
    if (state.cart.coupon) writeRaw(KEYS.coupon, state.cart.coupon);
    else writeRaw(KEYS.coupon, "");
  }
  /* ★ v17-W1: المفضلة scoped بالمالك — مخبأ كل مالك + المالك + سجل الدمج.
     المفتاح العام القديم (atyab-wishlist) يُكتب لتوافق النسخ السابقة فقط
     ولا يُقرأ وحده أبداً عند الإقلاع (wishlistSlice يفسره بالمالك).
     ★ FE17-F02: بصمة المراقبة تشمل dirtyAdd — تغير سجل النيات يُحفظ
     حتى لو بقيت ids نفسها (كان الضياع عند reload مع عمليات معلقة).
     ★ FE19-5: البصمة والمخبأ يشملان dirtyDel وسجل ops — نيات الحذف تنجو
     من reload وتُدفع في السحب التالي. */
  const wish = JSON.stringify(state.wishlist.ids);
  const wishDirty = JSON.stringify(state.wishlist.dirtyAdd || []);
  const wishDel = JSON.stringify(state.wishlist.dirtyDel || []);
  const wishOps = JSON.stringify(state.wishlist.ops || []);
  const wOwner = state.wishlist.ownerId != null ? Number(state.wishlist.ownerId) : null;
  const wKey = wOwner == null ? "guest" : "c:" + String(wOwner);
  if (wish !== last.wishlist || wishDirty !== last.wishDirty || wishDel !== last.wishDel || wishOps !== last.wishOps || String(wOwner) !== String(last.wishOwner)) {
    last.wishlist = wish;
    last.wishDirty = wishDirty;
    last.wishDel = wishDel;
    last.wishOps = wishOps;
    last.wishOwner = String(wOwner);
    writeJSON(KEYS.wishlist, state.wishlist.ids);
    try {
      const stash = readJSON(KEYS.wishlistByOwner, null) || {};
      stash[wKey] = {
        ids: state.wishlist.ids,
        dirtyAdd: state.wishlist.dirtyAdd || [],
        dirtyDel: state.wishlist.dirtyDel || [],
        ops: cleanWishOps(state.wishlist.ops || [])
      };
      writeJSON(KEYS.wishlistByOwner, stash);
    } catch (e) {}
    try { writeJSON(KEYS.wishlistOwner, wOwner == null ? 0 : Number(wOwner)); } catch (e) {}
  }
  const wMerged = JSON.stringify(state.wishlist.merged || {});
  if (wMerged !== last.wishMerged) {
    last.wishMerged = wMerged;
    writeJSON(KEYS.wishlistMerged, state.wishlist.merged || {});
  }
}

store.subscribe(persist);
persist();

/* للتصحيح فقط في التطوير — يُحجب تماماً في الإنتاج حتى لا يكشف حالة الجلسة/السلة من الكونسول */
if (typeof window !== "undefined" && typeof process !== "undefined" && process.env && process.env.NODE_ENV !== "production") {
  window.__ATYAB_STORE__ = store;
}

export default store;
