import { createSlice, createAsyncThunk, createSelector } from "@reduxjs/toolkit";
import { api, apiUrl, ENDPOINTS, atyabLog } from "../api.js";

export const SETTINGS_DEFAULTS = {
  siteEnabled: true,
  offlineMessageAr: "المتجر يعود قريباً — نعتذر عن الإزعاج، ويمكنك مراسلتنا على الواتساب.",
  offlineMessageEn: "We are back shortly — sorry for the interruption. Message us on WhatsApp.",
  storeNameAr: "أطياب الجاسم",
  storeNameEn: "Atyab Al-Jasem",
  defaultCurrencyCode: "AED",
  vatRate: 0.05,
  vatIncluded: false,
  freeShippingThreshold: 300,
  freeShippingThresholdGcc: 500,
  shippingFlatFee: 25,
  shippingGccFee: 65,
  cashOnDeliveryEnabled: true,
  freeReturnDays: 2,
  termsVersion: "2026-11",
  returnsRequireUnopened: true,
  supportPhone: "+971508755752",
  supportWhatsapp: "+971508755752",
  supportEmail: "husseyni20221@gmail.com",
  workingHoursAr: "السبت–الخميس · 10 صباحاً – 10 مساءً",
  workingHoursEn: "Sat–Thu · 10:00 – 22:00",
  lastUpdatedAt: ""
};

function normalize(raw) {
  const r = raw || {};
  const out = Object.assign({}, SETTINGS_DEFAULTS);
  Object.keys(SETTINGS_DEFAULTS).forEach(function (k) {
    if (r[k] != null && r[k] !== "") out[k] = r[k];
  });
  out.siteEnabled = r.siteEnabled !== false;
  out.vatRate = Number(r.vatRate) >= 0 ? Number(r.vatRate) : SETTINGS_DEFAULTS.vatRate;
  out.vatIncluded = !!r.vatIncluded;
  out.freeShippingThreshold = Number(r.freeShippingThreshold) > 0 ? Number(r.freeShippingThreshold) : SETTINGS_DEFAULTS.freeShippingThreshold;
  out.freeShippingThresholdGcc = Number(r.freeShippingThresholdGcc) > 0 ? Number(r.freeShippingThresholdGcc) : SETTINGS_DEFAULTS.freeShippingThresholdGcc;
  out.shippingFlatFee = r.shippingFlatFee != null ? Number(r.shippingFlatFee) : SETTINGS_DEFAULTS.shippingFlatFee;
  out.shippingGccFee = r.shippingGccFee != null ? Number(r.shippingGccFee) : SETTINGS_DEFAULTS.shippingGccFee;
  out.cashOnDeliveryEnabled = r.cashOnDeliveryEnabled !== false;
  /* ★ الباك إند قد يرجع رقماً مقنّعاً (+971 5X XXX XXXX) — تجاهله للافتراضي الحقيقي */
  if (/x/i.test(String(out.supportPhone || ""))) out.supportPhone = SETTINGS_DEFAULTS.supportPhone;
  if (/x/i.test(String(out.supportWhatsapp || ""))) out.supportWhatsapp = SETTINGS_DEFAULTS.supportWhatsapp;
  return out;
}

export const getStoreSettings = createAsyncThunk(
  "settings/get",
  async function (_, { rejectWithValue }) {
    try {
      atyabLog("settings FETCH");
      const res = await api.get(apiUrl(ENDPOINTS.storeSettings));
      atyabLog("settings CACHED");
      return normalize(res.data);
    } catch (err) {
      atyabLog("settings FAIL");
      return rejectWithValue("تعذر جلب إعدادات المتجر");
    }
  },
  {
    condition: function (force, { getState }) {
      const s = getState().settings;
      if (!s) return true;
      if (s.status === "loading") { atyabLog("settings IN-FLIGHT"); return false; }
      if (force === true) { atyabLog("settings FORCE"); return true; }
      if (s.status === "succeeded" && Date.now() - (s.lastFetchedAt || 0) < 120000) { atyabLog("settings CACHE-HIT"); return false; }
      atyabLog("settings MISS");
      return true;
    }
  }
);

/* ★ فحص خفيف عند التنقل (الرئيسية/السلة/الأمنيات): حالة الفتح فقط */
export const getStoreOpenStatus = createAsyncThunk(
  "settings/openStatus",
  async function (_, { rejectWithValue }) {
    try {
      const res = await api.get(apiUrl(ENDPOINTS.storeOpen));
      const open = res && res.data && typeof res.data.isOpen !== "undefined" ? !!res.data.isOpen : true;
      atyabLog("openStatus", open ? "OPEN" : "CLOSED");
      return open;
    } catch (err) {
      atyabLog("openStatus FAIL");
      return rejectWithValue("fail");
    }
  }
);

const slice = createSlice({
  name: "settings",
  initialState: { data: Object.assign({}, SETTINGS_DEFAULTS), status: "idle", error: "", lastFetchedAt: 0 },
  reducers: {},
  extraReducers: function (builder) {
    builder
      .addCase(getStoreSettings.pending, function (state) {
        state.status = "loading";
      })
      .addCase(getStoreSettings.fulfilled, function (state, action) {
        state.status = "succeeded";
        state.data = action.payload;
        state.lastFetchedAt = Date.now();
      })
      .addCase(getStoreSettings.rejected, function (state, action) {
        state.status = "failed";
        state.error = action.payload || "fail";
      })
      .addCase(getStoreOpenStatus.fulfilled, function (state, action) {
        state.data.siteEnabled = action.payload;
        state.lastFetchedAt = Date.now();
      });
  }
});

export function selectStoreSettings(state) {
  return (state.settings && state.settings.data) || SETTINGS_DEFAULTS;
}

export function selectSiteEnabled(state) {
  const d = selectStoreSettings(state);
  return d.siteEnabled !== false;
}

export function digitsOf(phone) {
  return String(phone == null ? "" : phone).replace(/\D/g, "");
}

/* ★ مذكّر: نفس المرجع ما دامت الإعدادات كما هي — بلا تحذيرات rerender */
export const selectSupport = createSelector([selectStoreSettings], function (d) {
  const src = d || SETTINGS_DEFAULTS;
  return {
    phone: src.supportPhone || SETTINGS_DEFAULTS.supportPhone,
    whatsapp: src.supportWhatsapp || SETTINGS_DEFAULTS.supportWhatsapp,
    whatsappDigits: (function () {
      const wd = digitsOf(src.supportWhatsapp || SETTINGS_DEFAULTS.supportWhatsapp);
      return wd.length >= 7 ? wd : digitsOf(SETTINGS_DEFAULTS.supportWhatsapp);
    })(),
    email: src.supportEmail || SETTINGS_DEFAULTS.supportEmail,
    hoursAr: src.workingHoursAr || "",
    hoursEn: src.workingHoursEn || ""
  };
});

export default slice.reducer;
