/* ============================================================
   أطياب الجاسم (React) — شريحة الكتالوج (catalogSlice)
   تفاصيل العرض: أي كتالوج نشط (عطور/بخور)، الترتيب، وفلترة البحث.
   ★ الصفحتان PerfumePage و BakhourPage تستدعيان نفس الكومبوننت ProductCard
     وتقرآن من هنا — فلا تكرار للقوائم.
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";

/* "" = بلا فلتر (نفس مفتاح شريحة «الكل» في Search.jsx) */
const DEFAULT_SEARCH = { query: "", type: "", gender: "" };

const slice = createSlice({
  name: "catalog",
  initialState: {
    active: "perfumes", /* الكتالوج الذي تستعمله القوائم المشتركة */
    status: "idle", /* idle | loading | succeeded | failed — يقود السكيلتون */
    sort: "bestseller",
    search: DEFAULT_SEARCH
  },
  reducers: {
    setActive: function (state, action) {
      const k = action.payload;
      state.active = k === "incense" || k === "ouds" || k === "mists" || k === "lotions" || k === "mukhamaria" || k === "hair" ? k : "perfumes";
    },
    setSort: function (state, action) {
      if (action.payload) state.sort = action.payload;
    },
    setStatus: function (state, action) {
      state.status = action.payload || "idle";
    },
    setSearch: function (state, action) {
      const patch = action.payload || {};
      state.search = {
        query: patch.query == null ? state.search.query : String(patch.query),
        type: patch.type == null ? state.search.type : patch.type,
        gender: patch.gender == null ? state.search.gender : patch.gender
      };
    },
    setSearchQuery: function (state, action) {
      state.search.query = String(action.payload == null ? "" : action.payload);
    },
    resetSearch: function (state) {
      state.search = { ...DEFAULT_SEARCH };
    }
  }
});

export const catalogActions = slice.actions;
export const catalogReducer = slice.reducer;
export const PERFUMES = "perfumes";
export const INCENSE = "incense";
