/* أطياب الجاسم — تأجيل العمل غير الحرِج إلى خمول المتصفح (PageSpeed جولة 2).
   يُستخدم لجلب المراجعات/الفعاليات/حالة المتجر: لا شيء منها يلزم أول رسم،
   لكن إبقاءها في مسار الإقلاع كان يزاحم LCP على شبكة الجيل الرابع.
   في بيئة الاختبار (NODE_ENV=test) يُنفَّذ فوراً حتى لا تنكسر الـsuites. */

export function runIdle(fn, timeoutMs) {
  var wait = Number(timeoutMs) > 0 ? Number(timeoutMs) : 3000;
  try {
    if (typeof process !== "undefined" && process.env && process.env.NODE_ENV === "test") {
      fn();
      return 0;
    }
  } catch (e) {}
  try {
    if (typeof window !== "undefined" && typeof window.requestIdleCallback === "function") {
      return window.requestIdleCallback(function () { try { fn(); } catch (e) {} }, { timeout: wait });
    }
  } catch (e) {}
  try {
    return window.setTimeout(function () { try { fn(); } catch (e) {} }, 900);
  } catch (e) {
    return 0;
  }
}

export function cancelIdle(handle) {
  if (!handle) return;
  try {
    if (typeof window !== "undefined" && typeof window.cancelIdleCallback === "function") {
      window.cancelIdleCallback(handle);
      return;
    }
  } catch (e) {}
  try { window.clearTimeout(handle); } catch (e) {}
}
