/* أيقونة عامة */
/* أيقونات العلامات تُرسم مملوءة (fill) لا مخططةة — كشعاراتها الأصلية */
const BRAND_FILL = { instagram: 1, tiktok: 1, snapchat: 1, whatsapp: 1 };
export function Icon(props) {
  const name = props.name;
  const cls = props.className;
  const body = ICONS[name] != null ? ICONS[name] : ICONS.dot;
  const brand = !!BRAND_FILL[name] && !props.stroke;
  const fill = props.fill || (brand ? "currentColor" : "none");
  const extra = props.viewBox ? { viewBox: props.viewBox } : { viewBox: "0 0 24 24" };
  const nodes = parseSvgInner(body);
  return (
    <svg
      className={cls}
      viewBox={extra.viewBox}
      fill={fill}
      stroke={fill === "none" ? "currentColor" : "none"}
      strokeWidth={fill === "none" ? (props.strokeWidth || 1.7) : 0}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      {nodes}
    </svg>
  );
}

/* علم دولة */
export function Flag(props) {
  const code = FLAGS[props.code] ? props.code : "sa";
  const nodes = parseSvgInner(FLAGS[code]);
  return (
    <svg
      className={props.className}
      viewBox="0 0 24 16"
      preserveAspectRatio="none"
      aria-hidden="true"
      focusable="false"
    >
      {nodes}
    </svg>
  );
}

