/* شعارات طرق الدفع (تقريب نصّي — بلا صور علامات تجارية) */
export function PayMark(props) {
  const key = props.mark;
  if (key === "gpay") return <span className="pm-word pm-word--gpay"><b>G</b>&nbsp;Pay</span>;
  if (key === "visa") return <span className="pm-word pm-word--visa">VISA</span>;
  if (key === "mastercard") return <span className="pm-word pm-word--mc"><i></i><i></i></span>;
  if (key === "tabby") return <span className="pm-word pm-word--tabby">tabby</span>;
  if (key === "tamara") return <span className="pm-word pm-word--tamara">tamara</span>;
  if (key === "applepay") return <span className="pm-word pm-word--apple"><svg viewBox="0 0 384 512" width="15" height="18" fill="currentColor" aria-hidden="true"><path d="M318.7 268.7c-.2-36.7 16.4-64.4 50-84.8-18.8-26.9-47.2-41.7-84.7-44.6-35.5-2.8-74.3 20.7-88.5 20.7-15 0-49.4-19.7-76.4-19.7C63.3 141.2 4 184.8 4 273.5q0 39.3 14.4 81.2c12.8 36.7 59 126.7 107.2 125.2 25.2-.6 43-17.9 75.8-17.9 31.8 0 48.3 17.9 76.4 17.9 48.6-.7 90.4-82.5 102.6-119.3-65.2-30.7-61.7-90-61.7-91.9zm-56.6-164.2c27.3-32.4 24.8-61.9 24-72.5-24.1 1.4-52 16.4-67.9 34.9-17.5 19.8-27.8 44.3-25.6 71.9 26.1 2 49.9-11.4 69.5-34.3z"/></svg>&nbsp;Pay</span>;
  if (key === "stcpay") return <span className="pm-word pm-word--stc">stc<b>pay</b></span>;
  if (key === "bank") return <Icon name="bank" className="pm-icon" />;
  if (key === "cod") return <Icon name="cash" className="pm-icon" />;
  return <Icon name="card" className="pm-icon" />;
}

/* صورة المنتج مع بديل عند الفشل — تُستخدم في كل البطاقات */
export function ProductImage(props) {
  const product = props.product || {};
  const src = props.src || product.image;
  if (!src) return <div className={"img-skeleton " + (props.className || "")} aria-hidden="true" />;
  return (
    <img
      src={src}
      alt={props.alt || product.name || ""}
      loading={props.eager ? "eager" : "lazy"}
      decoding="async"
      className={props.className}
      width={props.width}
      height={props.height}
      onError={function (e) {
        const img = e.currentTarget;
        if (product.placeholder && img.dataset.swapped !== "1") {
          img.dataset.swapped = "1";
          img.src = product.placeholder;
        }
        if (props.onFail) props.onFail(e);
      }}
    />
  );
}
