/* ============================================================
   أطياب الجاسم (React) — المُنتقيات (selectors)

   كل ما يُحسَب من حالة Redux يعيش هنا: تحويل العملة، حساب الفاتورة،
   أسعار العروض وعدّادها، ترتيب القوائم، وتفاصيل قطع العربة.
   لا كومبوننت يحسب سعراً بنفسه — يقرأ من هنا فقط.
   ============================================================ */

import { useMemo } from "react";
import { useSelector } from "react-redux";
import { createSelector } from "@reduxjs/toolkit";
import {
  ATYAB_byId,
  ATYAB_catalog,
  ATYAB_offerById
} from "../data/products.js";
import { ATYAB_CURRENCIES } from "../data/appConfig.js";
import {
  FREE_SHIP_OVER,
  FREE_SHIP_OVER_GCC,
  SHIP_FEE,
  VAT_RATE,
  COUPONS
} from "./shopConstants.js";
import { genderLabelOf } from "../i18n.js";
import { KEYS, readJSON, writeJSON } from "./persist.js";

/* ============================================================
   1) العملة — الأسعار مخزَّنة بالدرهم الإماراتي دائماً (محاسبة المالك والفاتورة)، والتحويل عند العرض فقط
   ============================================================ */
export function currencyMeta(code) {
  const list = ATYAB_CURRENCIES || [];
  for (let i = 0; i < list.length; i++) {
    if (list[i].key === code) return list[i];
  }
  return (
    list[0] || {
      key: "AED",
      label: "درهم إماراتي (د.إ)",
      short: "درهم إماراتي",
      symbol: "د.إ",
      symbolEn: "AED",
      rate: 1,
      decimals: 0,
      position: "after"
    }
  );
}

function groupNumber(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function symbolOf(meta, lang) {
  return lang === "en" && meta.symbolEn ? meta.symbolEn : meta.symbol;
}

function valueOf(stored, meta) {
  const dec = meta.decimals || 0;
  const parts = ((Number(stored) || 0) * (meta.rate || 1)).toFixed(dec).split(".");
  parts[0] = groupNumber(parts[0]);
  return parts.join(".");
}

/* كائن العملة الكامل — يُستخدم داخل الكومبوننتات */
export function makeMoneyFrom(meta, lang) {
  const symbol = symbolOf(meta, lang);
  const before = meta.position === "before";
  return {
    meta: meta,
    code: meta.key,
    symbol: symbol,
    before: before,
    /* مبلغ بلا رمز: 389 / 397.21 / 32.497 */
    amount: function (stored) {
      return valueOf(stored, meta);
    },
    /* مع الرمز: «389 د.إ» أو «$105.92» */
    format: function (stored) {
      const value = valueOf(stored, meta);
      if (before) return (symbol.length > 1 ? symbol + " " : symbol) + value;
      return value + " " + symbol;
    },
    /* أجزاء جاهزة للرسم: { before, symbol, value } */
    parts: function (stored) {
      return { before: before, symbol: symbol, value: valueOf(stored, meta) };
    }
  };
}

export function makeMoney(lang, code) {
  return makeMoneyFrom(currencyMeta(code), lang);
}

/* خطّاف للكومبوننتات */
export function useMoney() {
  const lang = useSelector(function (s) {
    return s.ui.language;
  });
  const code = useSelector(function (s) {
    return s.user.profile.currency;
  });
  /* مرجع ثابت ما دامت اللغة والعملة كما هما — فلا نُجبر الأبناء على إعادة الرسم */
  return useMemo(
    function () {
      return makeMoney(lang, code);
    },
    [lang, code]
  );
}

/* ============================================================
   2) العروض — الموعد (مناسبة حقيقية أو عدّاد متجدّد) + السعر الساري
   ============================================================ */
const MAX_AHEAD_MS = 45 * 86400e3;
const MIN_AHEAD_MS = 2 * 3600e3;
const deadlineCache = {};

function endOfDay(ms) {
  const d = new Date(ms);
  d.setHours(23, 59, 59, 0);
  return d.getTime();
}

export function deadlineOf(offer) {
  if (!offer) return { key: "", start: 0, end: 0, mode: "rolling" };
  if (deadlineCache[offer.key]) return deadlineCache[offer.key];

  const now = Date.now();
  const c = offer.countdown || {};
  let rec = null;

  /* 1) مناسبة قريبة (خلال ٤٥ يوماً) → موعد حقيقي */
  if (c.month && c.day) {
    const year = new Date(now).getFullYear();
    for (let k = 0; k < 2 && !rec; k++) {
      const base = new Date(year + k, c.month - 1, c.day, 0, 0, 0, 0).getTime();
      const end = endOfDay(base + (Number(c.windowDays) || 0) * 86400e3);
      if (end - now > MAX_AHEAD_MS) break;
      if (end - now > MIN_AHEAD_MS) {
        rec = {
          key: offer.key,
          start: base - (Number(c.leadDays) || 0) * 86400e3,
          end: end,
          mode: "occasion"
        };
      }
    }
  }

  /* 2) وإلا عدّاد متجدّد محفوظ في متصفّح الزائر */
  if (!rec) {
    const store = readJSON(KEYS.offerDeadlines, {}) || {};
    const hours = Number(c.hours) > 0 ? Number(c.hours) : 72;
    const saved = Number(store[offer.key]) || 0;
    const endMs = saved > now + MIN_AHEAD_MS ? saved : now + hours * 3600e3;
    if (endMs !== saved) {
      store[offer.key] = endMs;
      writeJSON(KEYS.offerDeadlines, store);
    }
    rec = { key: offer.key, start: endMs - hours * 3600e3, end: endMs, mode: "rolling" };
  }

  deadlineCache[offer.key] = rec;
  return rec;
}

export function isOfferLive(offer) {
  const rec = deadlineOf(offer);
  if (rec.end <= Date.now() && rec.mode === "rolling") delete deadlineCache[offer.key];
  return rec.end > Date.now();
}

/* سعر العرض الساري لمنتج — تقرأه العربة أيضاً حتى يرى العميل نفس السعر */
export function offerPriceOf(id) {
  const offer = ATYAB_offerById ? ATYAB_offerById(Number(id)) : null;
  if (!offer || !isOfferLive(offer)) return null;
  const price = Number(offer.price);
  return price > 0 ? price : null;
}

export function offerForProduct(id) {
  const offer = ATYAB_offerById ? ATYAB_offerById(Number(id)) : null;
  return offer && isOfferLive(offer) ? offer : null;
}

/* سعر القطعة الواحدة: سعر العرض إن كان سارياً، وإلا سعر المتجر */
export function unitPriceOf(product) {
  if (!product) return 0;
  const offer = offerPriceOf(product.id);
  return typeof offer === "number" && offer > 0 ? offer : product.price;
}

/* أجزاء العدّاد { d, h, m, s } */
export function partsOf(rem) {
  const total = Math.floor(Math.max(0, rem) / 1000);
  return {
    d: Math.floor(total / 86400),
    h: Math.floor(total / 3600) % 24,
    m: Math.floor(total / 60) % 60,
    s: total % 60
  };
}

const UNIT_NAMES = {
  d: { ar: { one: "يوم", two: "يوم", few: "أيام", many: "يوماً" }, en: { one: "day", two: "days", few: "days", many: "days" } },
  h: { ar: { one: "ساعة", two: "ساعة", few: "ساعات", many: "ساعة" }, en: { one: "hour", two: "hours", few: "hours", many: "hours" } },
  m: { ar: { one: "دقيقة", two: "دقيقة", few: "دقائق", many: "دقيقة" }, en: { one: "minute", two: "minutes", few: "minutes", many: "minutes" } },
  s: { ar: { one: "ثانية", two: "ثانية", few: "ثوانٍ", many: "ثانية" }, en: { one: "second", two: "seconds", few: "seconds", many: "seconds" } }
};

export function unitName(kind, n, lang) {
  const forms = UNIT_NAMES[kind][lang === "en" ? "en" : "ar"];
  if (n === 1) return forms.one;
  if (n === 2) return forms.two;
  if (n >= 3 && n <= 10) return forms.few;
  return forms.many;
}

export function pad2(n) {
  return (n < 10 ? "0" : "") + n;
}

/* لون العرض بصيغة rgb للاستعمال في rgba() */
export function rgbOf(hex) {
  let h = String(hex || "").replace("#", "");
  if (h.length === 3) h = h.charAt(0) + h.charAt(0) + h.charAt(1) + h.charAt(1) + h.charAt(2) + h.charAt(2);
  if (h.length !== 6 || /[^0-9a-fA-F]/.test(h)) return "21,115,71";
  return parseInt(h.slice(0, 2), 16) + "," + parseInt(h.slice(2, 4), 16) + "," + parseInt(h.slice(4, 6), 16);
}

/* ============================================================
   3) الكتالوجات والمنتجات
   ============================================================ */
export function selectCatalogKey(state) {
  return state.catalog.active;
}

export function selectSortKey(state) {
  return state.catalog.sort;
}

export function selectCartRows(state) {
  return state.cart.rows;
}

export function selectCouponCode(state) {
  return state.cart.coupon || "";
}

export function selectCouponInfo(state) {
  return state.cart.couponInfo || null;
}

/* ★ إعدادات المتجر الحيّة (AED افتراضياً) — تُغذّي الفاتورة والشحن والضريبة */
export function selectStoreSettings(state) {
  return (state.settings && state.settings.data) || null;
}

function numOr(v, fallback) {
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

/* مصفوفة فارغة مشتركة — بدل إنشاء مرجع جديد في كل نداء */
const EMPTY_LIST = [];

/* ★ مدخلات المنتجات للـmemoized selectors: أي حساب يقرأ المنتجات عبر
   ATYAB_byId يجب أن يُدخل القوائم والصور صراحة — وإلا أعاد createSelector
   نتيجة قديمة بعد وصول المنتجات (المعرّفات وحدها لا تتغيّر).
   ★ يجب أن يبقى هذا التعريف فوق كل استخدام له — فاستخدامه قبل سطر
   الـconst يُسقط التطبيق كله بخطأ: Cannot access before initialization. */
function selectPerfumesList(state) {
  return state.perfumes && state.perfumes.list;
}
function selectOudsList(state) {
  return state.ouds && state.ouds.list;
}
function selectIncensesList(state) {
  return state.incenses && state.incenses.list;
}
/* ★ R23: قوائم «باقي المنتجات» — تُدخل في كل مُنتقٍ يعتمد على المنتجات
   حتى لا يعيد createSelector نتيجة قديمة بعد وصولها */
function selectMistsList(state) {
  return state.mists && state.mists.list;
}
function selectLotionsList(state) {
  return state.lotions && state.lotions.list;
}
function selectMukhamariaList(state) {
  return state.mukhamaria && state.mukhamaria.list;
}
function selectHairList(state) {
  return state.hair && state.hair.list;
}
function selectImagesMain(state) {
  return state.images && state.images.main;
}
function selectImagesGalleries(state) {
  return state.images && state.images.galleries;
}
const PRODUCT_INPUTS = [selectPerfumesList, selectOudsList, selectIncensesList, selectMistsList, selectLotionsList, selectMukhamariaList, selectHairList, selectImagesMain, selectImagesGalleries];

/* ★ قاعدة ثابتة: كل مُنتقٍ يُعيد مصفوفة أو كائناً جديداً يجب أن يكون مُغلَّفاً
   بـcreateSelector (أي memoized)، وإلا اشتكى React-Redux في وضع التطوير:
   "Selectors returned a different result when called with the same parameters"
   لأنّ useSelector يقارن بالمرجع (===) فيرى نتيجة «مختلفة» في كل نداء. */
export const selectActiveCatalog = createSelector([selectCatalogKey].concat(PRODUCT_INPUTS), function (active) {
  return ATYAB_catalog(active);
});

export const selectItems = createSelector([selectActiveCatalog], function (catalog) {
  return (catalog && catalog.items) || EMPTY_LIST;
});

export function sortItems(items, sortKey) {
  const list = (items || []).slice();
  switch (sortKey) {
    case "rating":
      list.sort(function (a, b) {
        return (b.rating || 0) - (a.rating || 0) || (b.sales || 0) - (a.sales || 0);
      });
      break;
    case "price-desc":
      list.sort(function (a, b) {
        return unitPriceOf(b) - unitPriceOf(a);
      });
      break;
    case "price-asc":
      list.sort(function (a, b) {
        return unitPriceOf(a) - unitPriceOf(b);
      });
      break;
    default:
      list.sort(function (a, b) {
        return (b.sales || 0) - (a.sales || 0) || (b.rating || 0) - (a.rating || 0);
      });
  }
  return list;
}

export const selectSortedItems = createSelector([selectItems, selectSortKey], function (items, sortKey) {
  return sortItems(items, sortKey);
});

export function selectProductById(state, id) {
  return ATYAB_byId ? ATYAB_byId(Number(id)) : null;
}

export function selectProductCatalog(state, id) {
  const product = selectProductById(state, id);
  if (product && product.kind === "oud") return ATYAB_catalog("ouds");
  if (product && product.kind === "incense") return ATYAB_catalog("incense");
  if (product && product.kind === "perfume") return ATYAB_catalog("perfumes");
  return ATYAB_catalog("perfumes");
}

export function selectWishlistIds(state) {
  return state.wishlist.ids;
}

export const selectWishlistProducts = createSelector([selectWishlistIds].concat(PRODUCT_INPUTS), function (ids) {
  return ids
    .map(function (id) {
      return ATYAB_byId ? ATYAB_byId(id) : null;
    })
    .filter(Boolean);
});

export function selectSearchFilters(state) {
  return state.catalog.search;
}

export const selectCartCount = createSelector([selectCartRows], function (rows) {
  return rows.reduce(function (n, r) {
    return n + r.qty;
  }, 0);
});

export const selectCartIds = createSelector([selectCartRows], function (rows) {
  return rows.map(function (r) {
    return r.id;
  });
});

/* ============================================================
   4) العربة — تفاصيل القطع والفاتورة
   ============================================================ */
function cartRowsDetailedOf(rows) {
  return rows
    .map(function (row) {
      const product = ATYAB_byId ? ATYAB_byId(row.id) : null;
      if (!product) return null;
      const unitPrice = unitPriceOf(product);
      const lineOld = (product.oldPrice || unitPrice) * row.qty;
      const lineTotal = unitPrice * row.qty;
      const pct =
        product.oldPrice && product.oldPrice > unitPrice
          ? Math.round(((product.oldPrice - unitPrice) / product.oldPrice) * 100)
          : 0;
      return {
        id: row.id,
        qty: row.qty,
        product: product,
        unitPrice: unitPrice,
        lineOld: lineOld,
        lineTotal: lineTotal,
        pct: pct,
        meta: [product.size, product.kindLabel || genderLabelOf(product.gender, "ar")].filter(Boolean).join(" · "),
        offerName: product.offer || "",
        /* ★ ملاحظة الخادم على الصف (404 منتج/مخزون) — للشارة الحمراء */
        serverNote: row.serverNote != null ? String(row.serverNote) : null
      };
    })
    .filter(Boolean);
}

export const selectCartRowsDetailed = createSelector([selectCartRows].concat(PRODUCT_INPUTS), cartRowsDetailedOf);

/* ★ v17-T17: مصدّرة للاختبار (عتبة الشحن بعد الخصم 400→200/300) */
export function cartTotalsOf(rows, couponCode, settings, couponInfo, isGcc) {
  /* ★ العتبة/الأجرة/الضريبة من /api/store/settings — والثوابت احتياط فقط */
  const freeOver = isGcc
    ? (settings ? numOr(settings.freeShippingThresholdGcc, FREE_SHIP_OVER_GCC) : FREE_SHIP_OVER_GCC)
    : (settings ? numOr(settings.freeShippingThreshold, FREE_SHIP_OVER) : FREE_SHIP_OVER);
  const shipFee = settings ? numOr(settings.shippingFlatFee, SHIP_FEE) : SHIP_FEE;
  const vatRate = settings ? numOr(settings.vatRate, VAT_RATE) : VAT_RATE;
  const vatIncluded = settings ? !!settings.vatIncluded : true;
  let count = 0;
  let before = 0;
  let net = 0;
  rows.forEach(function (row) {
    count += row.qty;
    before += row.lineOld;
    net += row.lineTotal;
  });

  const offerSave = Math.max(0, before - net);
  const code = couponCode || "";
  const coupon = COUPONS[code] || null;
  const percent = coupon && coupon.type === "percent" ? Number(coupon.value) || 0 : 0;
  const fixed = coupon && coupon.type === "fixed" ? Number(coupon.value) || 0 : 0;
  /* ★ حُكم الخادم (discountAmount) يغلِب الحساب المحلي — فهو المرجع،
     والمحلي احتياط فقط قبل وصول الرد. كوبون الشحن يُصفّر الأجرة. */
  const serverShipFree = !!(couponInfo && couponInfo.code === code && couponInfo.freeShipping);
  const serverDiscount = couponInfo && couponInfo.code === code && couponInfo.serverDiscount != null
    ? Math.max(0, Math.min(net, Number(couponInfo.serverDiscount) || 0))
    : null;
  const discount = serverDiscount != null
    ? serverDiscount
    : Math.min(net, percent ? Math.round((net * percent) / 100) : fixed);
  const afterDiscount = Math.max(0, net - discount);
  const shipFree = count === 0 || afterDiscount >= freeOver || !!(coupon && coupon.type === "shipping") || serverShipFree;
  const shipping = shipFree ? 0 : shipFee;
  const sub = afterDiscount + shipping;
  /* ★ شاملة؟ نستخرجها للعرض — غير شاملة؟ نضيفها فوق المجموع */
  const vat = vatIncluded ? Math.round((sub * vatRate) / (1 + vatRate)) : Math.round(sub * vatRate);
  const total = vatIncluded ? sub : sub + vat;

  return {
    rows: rows,
    count: count,
    before: before,
    net: net,
    offerSave: offerSave,
    code: coupon ? code : "",
    coupon: coupon,
    percent: percent,
    discount: discount,
    shipping: shipping,
    shipFree: shipFree,
    total: total,
    vat: vat,
    vatRate: vatRate,
    vatIncluded: vatIncluded,
    freeOver: freeOver,
    shipFee: shipFee,
    saved: offerSave + discount,
    toFreeShip: Math.max(0, freeOver - afterDiscount)
  };
}

/* ★ عتبة الشحن المجاني حسب الدولة: الإمارات ٣٠٠ وغيرها من الخليج ٥٠٠ (من /api/store/settings، والثوابت احتياط) */
function selectShipIsGcc(state) {
  try {
    var r = state && state.user && state.user.profile && state.user.profile.region;
    var k = String(r == null ? "AE" : r).trim();
    return k !== "" && k !== "AE";
  } catch (e) { return false; }
}

export const selectCartTotals = createSelector([selectCartRowsDetailed, selectCouponCode, selectStoreSettings, selectCouponInfo, selectShipIsGcc], function (rows, coupon, settings, info, isGcc) {
  return cartTotalsOf(rows, coupon, settings, info, isGcc);
});

