/* ============================================================
   أطياب الجاسم (React) — دراور الجوال (Drawer)

   ★ R29: فُصل عن MainHeader.jsx في ملف مستقل داخل مجلد Headers —
     كل ما يخص قائمة الجوال يعيش هنا ولا شيء منه في MainHeader.
   · الخلفية (backdrop) + ورقة القائمة + رأس الدراور + أدواته +
     العروض + الروابط + زر «باقي المنتجات» + صندوق الأصناف + دخول/حسابي.
   · الحالة: mobileNavOpen من Redux (uiSlice)؛ وMainLayout يضيف
     body.nav-open الذي يحرك الأنيميشن في Main.css.
   ★ R30: زر «باقي المنتجات» — النص أقصى اليسار و«>» أقصى اليمين (ثابتة).
   ★ R31: الأصناف تظهر في صندوق مدمج تحت الزر مباشرة (مكان المربع
     الأحمر) بأنيميشن فتح/إغلاق — لا لوحة تملأ الشاشة ولا شيء خارجها.
     الفتح/الغلق inline بالكامل (grid-rows + opacity + visibility) فيعمل
     حتى مع CSS قديم؛ النصوص يسارًا. (مُختبَر آليًا: 0px ← 126px ← 0px)
   · دهن العود أول عناصر المجموعة (من MORE_ITEMS).
   ============================================================ */

import { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { PATHS, pathForPage } from "../../routes.js";
import { ATYAB_PAGES } from "../../data/appConfig.js";
import { NAV_ITEMS, MORE_ITEMS, MORE_PAGES } from "../../constants/navItems.js";
import { t } from "../../i18n.js";
import { selectCartTotals } from "../../redux/selectors.js";
import { Icon } from "../Source/Icons.jsx";

/* ★ R32: مسبار النسخة — نفّذ window.__DRAWER_VER__ في كونسول المتصفح،
   يجب أن تطبع "R32". إن طبعت قيمةًا أقدم أو undefined فالحزمة
   المنشورة قديمة (استبدال ناقص / بناء قديم / كاش).
   window.__DRAWER_MORE__ يعكس حالة الصندوق لحظة بلحظة (true/false). */
try {
  if (typeof window !== "undefined") {
    window.__DRAWER_VER__ = "R32";
    if (typeof window.__DRAWER_MORE__ === "undefined") window.__DRAWER_MORE__ = false;
  }
} catch (e) {}

/* وجهة أي زر في الدراور — تُقرأ من ATYAB_PAGES وتُحوَّل إلى مسار راوتر */
function target(key) {
  return pathForPage(key, ATYAB_PAGES);
}

export default function Drawer() {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const navOpen = useAppSelector(function (s) {
    return s.ui.mobileNavOpen;
  });
  /* ★ الشارة من الفاتورة المحسوبةة (منتجات موجودة فعلاً في الكتالوج) */
  const cartCount = useAppSelector(function (s) {
    return selectCartTotals(s).count;
  });
  /* ★ «حسابي» تُعرض فقط مع customerId حقيقي من الخادم */
  const session = useAppSelector(function (s) {
    return s.user.auth && s.user.auth.customerId ? s.user.session : null;
  });
  const catalogActive = useAppSelector(function (s) {
    return s.catalog.active;
  });
  /* ★ R31: صندوق «باقي المنتجات» المدمج — مطوي افتراضيًا */
  const [moreOpen, setMoreOpen] = useState(false);

  const isEn = language === "en";

  /* إغلاق الصندوق مع الدراور نفسه */
  useEffect(
    function () {
      if (!navOpen) setMoreOpen(false);
    },
    [navOpen]
  );

  /* إغلاق الصندوق عند نقرة خارج القائمة كلها أو تغيير المقاس */
  useEffect(
    function () {
      if (!moreOpen) return undefined;
      function onDown(e) {
        if (!e.target || !e.target.closest || !e.target.closest(".navmenu")) setMoreOpen(false);
      }
      function onClose() {
        setMoreOpen(false);
      }
      document.addEventListener("pointerdown", onDown);
      window.addEventListener("resize", onClose);
      return function () {
        document.removeEventListener("pointerdown", onDown);
        window.removeEventListener("resize", onClose);
      };
    },
    [moreOpen]
  );

  /* الزر النشط — يُشتق من مسار الراوتر الحالي */
  function activeKeyOf(pathname) {
    if (pathname === PATHS.perfumes) return "perfumes";
    if (pathname === PATHS.incense) return "incense";
    if (pathname === PATHS.ouds) return "ouds";
    if (pathname === PATHS.mists) return "mists";
    if (pathname === PATHS.lotions) return "lotions";
    if (pathname === PATHS.mukhamaria) return "mukhamaria";
    if (pathname === PATHS.hair) return "hair";
    if (pathname === PATHS.offers) return "offers";
    if (pathname === PATHS.contact) return "contact";
    if (pathname === PATHS.shipping) return "shipping";
    if (pathname === PATHS.branches) return "branches";
    if (pathname === PATHS.tracking) return "tracking";
    if (pathname === PATHS.profile || pathname === PATHS.wishlist) return "profile";
    if (pathname.indexOf(PATHS.product + "/") === 0) {
      if (catalogActive === "incense") return "incense";
      if (catalogActive === "ouds" || catalogActive === "mists" || catalogActive === "lotions" || catalogActive === "mukhamaria" || catalogActive === "hair") return catalogActive;
      return "perfumes";
    }
    return "";
  }

  const active = activeKeyOf(location.pathname);

  function moreLabel() {
    return isEn ? t("en", "nav.more", "باقي المنتجات") : "باقي المنتجات";
  }

  /* ★ الدخول من الدراور يعود لنفس الصفحة بعد الدخول */
  const loginFrom = location.pathname + (location.search || "");

  const moreOn = MORE_PAGES.indexOf(active) !== -1;

  /* ★ R32: قلب + تشخيص فوري في الكونسول */
  function toggleMore() {
    setMoreOpen(function (v) {
      var n = !v;
      try {
        window.__DRAWER_MORE__ = n;
        if (window.console && window.console.log) window.console.log("[drawer] more:", n ? "open" : "closed");
      } catch (e) {}
      return n;
    });
  }

  /* ★ R31: زر «باقي المنتجات» — النص أقصى اليسار و«>» أقصى اليمين،
     وتحته مباشرة صندوق الأصناف المدمج بأنيميشن فتح/إغلاق. */
  function moreButton() {
    return (
      <li key="more" className={"nav-more-li nav-more-accordion" + (moreOn ? " is-on" : "") + (moreOpen ? " open" : "")}>
        <button
          type="button"
          className={"nav-more-btn" + (moreOpen ? " open" : "") + (moreOn ? " active" : "")}
          style={{ display: "flex", flexDirection: "row", direction: "ltr", justifyContent: "space-between", alignItems: "center", width: "100%" }}
          aria-expanded={moreOpen ? "true" : "false"}
          aria-controls="moreFlyout"
          onClick={toggleMore}
        >
          <span>{moreLabel()}</span>
          <Icon name="chevRight" className="more-chev" strokeWidth={2} />
        </button>
        <div
          id="moreFlyout"
          aria-hidden={moreOpen ? "false" : "true"}
          style={{
            display: "grid",
            gridTemplateRows: moreOpen ? "1fr" : "0fr",
            opacity: moreOpen ? 1 : 0,
            visibility: moreOpen ? "visible" : "hidden",
            transition: moreOpen
              ? "grid-template-rows 0.38s ease, opacity 0.3s ease, visibility 0s 0s"
              : "grid-template-rows 0.38s ease, opacity 0.3s ease, visibility 0s 0.38s"
          }}
        >
          <ul
            className="nav-more-list"
            onClick={function (e) {
              try {
                if (e.target && e.target.closest && e.target.closest("a")) dispatch(uiActions.setMobileNav(false));
              } catch (err) {}
            }}
            style={{ overflow: "hidden", minHeight: 0, margin: 0, padding: 0, listStyle: "none", position: "static", display: "grid", gap: 2, width: "100%", transform: "none" }}
          >
            {MORE_ITEMS.map(function (item) {
              return (
                <li key={item.page}>
                  <Link
                    to={target(item.page)}
                    data-page={item.page}
                    className={active === item.page ? "active" : ""}
                    aria-current={active === item.page ? "page" : undefined}
                    tabIndex={moreOpen ? undefined : -1}
                    style={{ display: "block", textAlign: "left" }}
                  >
                    {isEn ? t("en", item.i18n, item.label) : item.label}
                  </Link>
                </li>
              );
            })}
          </ul>
        </div>
      </li>
    );
  }

  return (
    <>
      <div
        className="nav-backdrop"
        aria-hidden="true"
        onClick={function () {
          dispatch(uiActions.setMobileNav(false));
        }}
      />
      <ul
        onClick={function (e) {
          if (!navOpen) return;
          /* النقر على الخلفية (لا على رابط) يُغلق القائمة */
          if (e.target === e.currentTarget) {
            dispatch(uiActions.setMobileNav(false));
            return;
          }
          /* النقر على أي رابط داخل الدراور يُغلقها فورًا */
          try {
            if (e.target && e.target.closest && e.target.closest("a")) dispatch(uiActions.setMobileNav(false));
          } catch (err) {}
        }}
      >
        {/* رأس الدراور: الشعار يمينًا وزر الإغلاق أقصى اليسار */}
        <li className="nav-drawer-head">
          <span className="nav-drawer-brand">
            <span className="logo-mark logo-mark--emblem" aria-hidden="true">
              <img
                src={(process.env.PUBLIC_URL || "") + "/atyab-emblem.webp"}
                width="100"
                height="191"
                decoding="async"
                alt=""
                onError={function (e) { try { e.currentTarget.style.display = "none"; } catch (err) {} }}
              />
            </span>
            <span className="sitename">
              أطياب الجاسم<small>ATYAB AL-JASEM</small>
            </span>
          </span>
          <button
            className="nav-drawer-close"
            type="button"
            aria-label={isEn ? "Close menu" : "إغلاق القائمة"}
            title={isEn ? "Close" : "إغلاق"}
            onClick={function () {
              dispatch(uiActions.setMobileNav(false));
            }}
          >
            <Icon name="x" strokeWidth={2.1} />
          </button>
        </li>
        {/* أدوات أعلى الدراور: بحث · مفضلة · إضاءة · سلة */}
        <li className="nav-drawer-tools" aria-label={isEn ? "Quick tools" : "أدوات سريعة"}>
          <button
            className="tool-btn"
            type="button"
            aria-label={isEn ? "Search" : "البحث"}
            title={isEn ? "Search" : "البحث"}
            onClick={function () {
              dispatch(uiActions.setMobileNav(false));
              navigate(target("search"));
            }}
          >
            <Icon name="search" strokeWidth={1.8} />
          </button>
          <button
            className="tool-btn"
            id="wishlistBtnDrawer"
            type="button"
            aria-label={isEn ? "Wishlist" : "المفضلة"}
            title={isEn ? "Wishlist" : "المفضلة"}
            onClick={function () {
              dispatch(uiActions.setMobileNav(false));
              navigate(PATHS.wishlist);
            }}
          >
            <Icon name="heart" />
          </button>
          <button
            className="theme-toggle"
            type="button"
            aria-label={isEn ? "Dark / light mode" : "تبديل الوضع الليلي والنهاري"}
            title={isEn ? "Dark / light mode" : "الوضع الليلي / النهاري"}
            onClick={function () {
              dispatch(uiActions.toggleTheme());
            }}
          >
            <Icon name="moon" className="ico ico-moon" />
            <Icon name="sun" className="ico ico-sun" />
          </button>
          <button
            className="tool-btn"
            type="button"
            aria-label={(isEn ? "Shopping cart" : "عربة التسوق") + (cartCount > 0 ? " — " + cartCount : "")}
            title={isEn ? "Shopping cart" : "عربة التسوق"}
            onClick={function () {
              dispatch(uiActions.setMobileNav(false));
              navigate(target("cart"));
            }}
          >
            <Icon name="cart" />
            <span className="tool-badge" id="cartCountDrawer" hidden={cartCount <= 0}>
              {cartCount > 99 ? "99+" : cartCount}
            </span>
          </button>
        </li>
        <li className="nav-offers-li">
          <Link to={target("offers")} className={"nav-offers" + (active === "offers" ? " active" : "")} data-page="offers">
            <Icon name="tag" strokeWidth={1.8} />
            <span>{isEn ? t("en", "nav.offers", "العروض") : "العروض"}</span>
            <i className="nav-offers-spark" aria-hidden="true" />
          </Link>
        </li>

        {NAV_ITEMS.map(function (item) {
          const li = (
            <li key={item.page}>
              <Link
                to={target(item.page)}
                data-page={item.page}
                className={active === item.page ? "active" : ""}
                aria-current={active === item.page ? "page" : undefined}
              >
                {isEn ? t("en", item.i18n, item.label) : item.label}
              </Link>
            </li>
          );
          /* «باقي المنتجات» بعد البخور مباشرة */
          if (item.page !== "incense") return li;
          return [li, moreButton()];
        })}

        {/* العضو يرى «حسابي»، والزائر يرى «تسجيل الدخول» */}
        {session ? (
        <li>
          <Link
            to={target("profile")}
            data-page="profile"
            className={active === "profile" ? "active" : ""}
            aria-current={active === "profile" ? "page" : undefined}
          >
            {isEn ? "My account" : "حسابي"}
          </Link>
        </li>
        ) : (
        <li className="nav-login-li">
          <Link
            className="btn-getstarted nav-login-btn"
            to={target("login")}
            state={{ from: loginFrom }}
            data-page="login"
          >
            {isEn ? "Log in" : "تسجيل الدخول"}
          </Link>
        </li>
        )}
      </ul>
    </>
  );
}
