import { createProductsSlice } from "./productsFactory.js";
import { ENDPOINTS, mockGetAllOuds } from "../api.js";

/* ============================================================
   أطياب الجاسم — شريحة العود (عود فقط)
   نفس نمط شريحة العطور تماماً: { list, status, error } +
   getAllOuds للقراءة فقط بشرط عدم التكرار والقائمة ممتلئة.
   ============================================================ */

const base = createProductsSlice({
  sliceName: "ouds",
  kind: "oud",
  kindGroup: "oud",
  kindLabelAr: "دهن العود",
  kindLabelEn: "Oud Oils",
  searchType: "oud",
  endpoint: ENDPOINTS.getAllOuds,
  mockFn: mockGetAllOuds
});

export const getAllOuds = base.getAll;
export const refreshOudsStock = base.refreshStock;
export const selectOudsList = base.selectList;
export const selectOudsStatus = base.selectStatus;
export const selectOudsError = base.selectError;
export const selectOudById = base.selectById;

export default base.reducer;
